      this.root.add(mesh); this.lotMeshes.push(mesh);
    }
    const curbMat = new THREE.MeshStandardMaterial({ color: 0x8f8f8a, roughness: 0.95 });
    const curbMesh = new THREE.InstancedMesh(curbGeo, curbMat, curbs.length);
    curbs.forEach(([x, z, r], i) => {
      tmp.position.set(x, 0.18, z); tmp.rotation.set(0, r, 0); tmp.updateMatrix();
      curbMesh.setMatrixAt(i, tmp.matrix);
    });
    this.root.add(curbMesh);
  }

  districtForBlock(bi, bj, special) {
    if (special === 'park') return 'park';
    if (special === 'suburb') return 'suburb';
    if (special === 'industrial') return 'industrial';
    if (special === 'airport') return 'airport';
    if (bj <= 1) return 'industrial';
    if (bi >= 6 && bj >= 2 && bj <= 5) return 'suburb';
    if (bj >= 6) return 'waterfront';
    if (bi <= 2 && bj >= 3) return 'residential';
    if (bi >= 3 && bi <= 5 && bj >= 2 && bj <= 5) return 'downtown';
    return 'midtown';
  }

  buildBlockContent(block, rng) {
    const { bi, bj, x, z, district, special } = block;
    if (special === 'park') { this.buildPark(block, rng); return; }
    if (special === 'hospital') { this.buildHospital(block); return; }
    if (special === 'police') { this.buildPolice(block); return; }
    if (special === 'fire') { this.buildFireStation(block); return; }
    if (special === 'garage') { this.buildGarage(block); return; }
    if (special === 'dealership') { this.buildDealership(block); return; }
    if (special === 'apartment') { this.buildApartment(block); return; }
    if (special === 'shop') { this.buildShop(block); return; }
    if (special === 'office') { this.buildOffice(block); return; }
    if (special === 'hotel') { this.buildHotel(block); return; }
    if (special === 'industrial') { this.buildFactory(block, rng); return; }
    if (district === 'downtown') this.buildDowntown(block, rng);
    else if (district === 'industrial') this.buildIndustrial(block, rng);
    else if (district === 'suburb') this.buildSuburb(block, rng);
    else if (district === 'waterfront') this.buildWaterfront(block, rng);
    else this.buildMidrise(block, rng);
  }

  buildingMaterial(palette, variant = 0) {
    return this.palettes[palette][variant % this.palettes[palette].length];
  }

  facadeGeometry(w, h, d) {
    const geo = new THREE.BoxGeometry(w, h, d);
    const uv = geo.attributes.uv;
    const reps = [
      [d, h], [d, h], [w, d], [w, d], [w, h], [w, h],
    ];
    for (let f = 0; f < 6; f++) {
      const rx = reps[f][0] / 12, ry = reps[f][1] / 13;
      for (let k = 0; k < 4; k++) {
        const idx = f * 4 + k;
        uv.setXY(idx, uv.getX(idx) * rx, uv.getY(idx) * ry);
      }
    }
    uv.needsUpdate = true;
    return geo;
  }

  addBuilding(x, z, w, d, h, palette, variant, opts = {}) {
    const mat = this.buildingMaterial(palette, variant);
    const roof = opts.roofMat || this.roofMat;
    const geo = this.facadeGeometry(w, h, d);
    const mesh = new THREE.Mesh(geo, [mat, mat, roof, roof, mat, mat]);
    mesh.position.set(x, h / 2 + 0.15 + (opts.base || 0), z);
    mesh.castShadow = h > 14;
    mesh.receiveShadow = true;
    this.root.add(mesh);
    const collider = { minX: x - w / 2, maxX: x + w / 2, minZ: z - d / 2, maxZ: z + d / 2, height: h, type: 'building', mesh };
    this.colliders.push(collider);
    if (opts.extraColliders) {
      for (const c of opts.extraColliders) this.colliders.push(c);
    }
    return { mesh, collider };
  }

  addRoofDetails(x, z, w, d, topY, rng, kind = 'normal') {
    const g = new THREE.Group();
    g.position.set(x, topY, z);
    const boxCount = 1 + Math.floor(rng() * 3);
    for (let i = 0; i < boxCount; i++) {
      const bw = 1.4 + rng() * 2.6, bh = 0.7 + rng() * 1.5, bd = 1.4 + rng() * 2.4;
      const m = new THREE.Mesh(new THREE.BoxGeometry(bw, bh, bd), rng() > .5 ? this.metalMat : this.concreteMat);
      m.position.set((rng() - .5) * (w - bw - 2), bh / 2 + 0.15, (rng() - .5) * (d - bd - 2));
      m.castShadow = true; g.add(m);
    }
    if (kind === 'tower') {
      const spire = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.22, 8 + rng() * 12, 5), this.metalMat);
      spire.position.y = 4 + rng() * 4; g.add(spire);
      const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.26, 6, 6), this.warmMat);
      beacon.position.y = spire.position.y + spire.geometry.parameters.height / 2; g.add(beacon);
      this.animated.push({ type: 'beacon', mesh: beacon, phase: rng() * 6 });
    }
    if (kind === 'tower' && rng() > 0.5) {
      const crown = new THREE.Mesh(new THREE.BoxGeometry(w * 0.92, 0.45, d * 0.92), this.crownMat);
      crown.position.y = 0.35; g.add(crown);
    }
    if (rng() > 0.55) {
      const ac = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.8, 1.4), this.whiteMat);
      ac.position.set((rng() - .5) * w * .5, 0.55, (rng() - .5) * d * .5); g.add(ac);
    }
    this.root.add(g);
    return g;
  }

  buildDowntown(block, rng) {
    const { x, z } = block;
    const w = 34 + rng() * 26, d = 34 + rng() * 26;
    const h = 58 + rng() * 120;
    const offX = (rng() - .5) * (66 - w), offZ = (rng() - .5) * (66 - d);
    const bx = x + offX, bz = z + offZ;
    const variant = Math.floor(rng() * 4);
    const { mesh } = this.addBuilding(bx, bz, w, d, h, 'downtown', variant, { roofMat: this.roofMatDark });
    // podium
    const podH = 7 + rng() * 9;
    if (rng() > 0.35) {
      const pod = this.addBuilding(bx, bz, w + 8, d + 8, podH, 'downtown', (variant + 1) % 4, { roofMat: this.roofMat });
      pod.mesh.castShadow = true;
    }
    // setbacks
    if (h > 100 && rng() > .35) {
      const h2 = h * (0.18 + rng() * .12);
      this.addBuilding(bx, bz, w * .72, d * .72, h2, 'downtown', (variant + 2) % 4, { base: h, roofMat: this.roofMatDark });
    }
    this.addRoofDetails(bx, bz, w, d, h + 0.2, rng, h > 70 ? 'tower' : 'normal');
    // facade fins for glass towers
    if (variant < 2) {
      const finMat = new THREE.MeshStandardMaterial({ color: 0x9fb3c4, roughness: .4, metalness: .6 });
      for (let i = -2; i <= 2; i++) {
        const fin = new THREE.Mesh(new THREE.BoxGeometry(0.28, h * .94, 0.5), finMat);
        fin.position.set(bx + i * w / 6, h / 2 + .2, bz + d / 2 + 0.3);
        this.root.add(fin);
      }
    }
    if (h > 125) {
      const sign = new THREE.Mesh(new THREE.PlaneGeometry(18, 5), new THREE.MeshBasicMaterial({ map: billboardTexture('NOVA', 'ABOVE ALL', '#0a2d4d', '#1b6d91'), transparent: false }));
      sign.position.set(bx, h * .75, bz + d / 2 + 0.3);
      this.root.add(sign);
    }
  }

  buildMidrise(block, rng) {
    const { x, z } = block;
    const rows = rng() > .5 ? 2 : 1;
    for (let r = 0; r < rows; r++) {
      const w = 20 + rng() * 16, d = 18 + rng() * 14, h = 12 + rng() * 24;
      const bx = x + (rows === 2 ? (r - .5) * 30 : (rng() - .5) * 24);
      const bz = z + (rng() - .5) * (66 - d - 4);
      this.addBuilding(bx, bz, w, d, h, 'midrise', Math.floor(rng() * 4));
      this.addRoofDetails(bx, bz, w, d, h + .2, rng);
      if (rng() > .6) this.addBalconies(bx, bz, w, d, h, rng);
    }
  }

  addBalconies(x, z, w, d, h, rng) {
    const mat = new THREE.MeshStandardMaterial({ color: 0x5b5b58, roughness: .9 });
    const count = Math.floor((h - 4) / 4);
    const geo = new THREE.BoxGeometry(w * .55, .18, .9);
    for (let i = 0; i < count; i++) {
      const y = 4.5 + i * 4;
      if (y > h - 1) break;
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y, z + d / 2 + .45); this.root.add(m);
      const rail = new THREE.Mesh(new THREE.BoxGeometry(w * .55, .7, .06), this.glassMat);
      rail.position.set(x, y + .45, z + d / 2 + .88); this.root.add(rail);
    }
  }

  buildResidential(block, rng) { this.buildMidrise(block, rng); }

  buildSuburb(block, rng) {
    const { x, z } = block;
    for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) {
      const hx = x + (i - .5) * 31, hz = z + (j - .5) * 31;
      const w = 12 + rng() * 4, d = 10 + rng() * 4;
      const h = 3.6 + rng() * 2.4;
      const pal = Math.floor(rng() * 4);
      this.addBuilding(hx, hz, w, d, h, 'suburb', pal);
      // roof
      const roof = new THREE.Mesh(new THREE.ConeGeometry(1, 1, 4), new THREE.MeshStandardMaterial({ color: [0x5b4237, 0x4a4a4a, 0x6b3d36, 0x454b48][pal], roughness: .92 }));
      roof.rotation.y = Math.PI / 4;
      roof.scale.set(w * .78, 2.6 + rng() * 1.2, d * .78);
      roof.position.set(hx, h + 1.45, hz);
      roof.castShadow = true;
      this.root.add(roof);
      // porch
      const porch = new THREE.Mesh(new THREE.BoxGeometry(3.2, .22, 2.2), this.woodMat);
      porch.position.set(hx + (rng() - .5) * 2, .55, hz + d / 2 + .9); this.root.add(porch);
      // garden
      const garden = new THREE.Mesh(new THREE.PlaneGeometry(10, 8), new THREE.MeshStandardMaterial({ color: 0x415d32, roughness: 1 }));
      garden.rotation.x = -Math.PI / 2; garden.position.set(hx + 8, .17, hz + 7); this.root.add(garden);
      // fence
      const fenceMat = this.woodMat;
      for (let f = 0; f < 5; f++) {
        const post = new THREE.Mesh(new THREE.BoxGeometry(.16, .9, .16), fenceMat);
        post.position.set(hx + 3, .6, hz + 11 + f * 1.4); this.root.add(post);
      }
      // driveway
      const drive = new THREE.Mesh(new THREE.PlaneGeometry(4, 12), new THREE.MeshStandardMaterial({ color: 0x77756e, roughness: 1 }));
      drive.rotation.x = -Math.PI / 2; drive.position.set(hx + 5, .16, hz + 8); this.root.add(drive);
      if (rng() > .6) this.tree(hx + 10, hz + 9, .8 + rng() * .4);
    }
  }

  buildIndustrial(block, rng) {
    const { x, z } = block;
    const w = 44 + rng() * 12, d = 30 + rng() * 16, h = 8 + rng() * 6;
    const bx = x + (rng() - .5) * 8, bz = z + (rng() - .5) * 8;
    this.addBuilding(bx, bz, w, d, h, 'industrial', Math.floor(rng() * 3), { roofMat: this.roofMatDark });
    this.addRoofDetails(bx, bz, w, d, h + .2, rng);
    // loading dock
    const dock = new THREE.Mesh(new THREE.BoxGeometry(w * .7, 1.4, 3.2), this.concreteMat);
    dock.position.set(bx, .85, bz + d / 2 + 1.6); dock.castShadow = true; this.root.add(dock);
    // containers
    const colors = [0x8e3b32, 0x2e5f7a, 0x7c6a2e, 0x356b4a, 0x7a4a32];
    for (let i = 0; i < 4 + Math.floor(rng() * 5); i++) {
      const cw = 6, ch = 2.6, cd = 2.5;
      const cont = new THREE.Mesh(new THREE.BoxGeometry(cw, ch, cd), new THREE.MeshStandardMaterial({ color: pick(colors), roughness: .8, metalness: .3 }));
      cont.position.set(x - 24 + rng() * 48, .6 + (rng() > .8 ? ch : 0), z + 24 + rng() * 8);
      cont.rotation.y = rng() > .5 ? 0 : Math.PI / 2;
      cont.castShadow = true; this.root.add(cont);
    }
  }

  buildWaterfront(block, rng) {
    const { x, z } = block;
    const w = 22 + rng() * 18, d = 24 + rng() * 16, h = 22 + rng() * 44;
    const bx = x + (rng() - .5) * 18, bz = z + (rng() - .5) * 10;
    this.addBuilding(bx, bz, w, d, h, 'midrise', Math.floor(rng() * 4));
    this.addRoofDetails(bx, bz, w, d, h + .2, rng, h > 50 ? 'tower' : 'normal');
    this.addBalconies(bx, bz, w, d, h, rng);
  }

  buildPark(block, rng) {
    const { x, z } = block;
    block.isPark = true;
    // path
    const pathMat = new THREE.MeshStandardMaterial({ color: 0x9a8f7a, roughness: 1 });
    const p1 = new THREE.Mesh(new THREE.PlaneGeometry(6, 68), pathMat);
    p1.rotation.x = -Math.PI / 2; p1.position.set(x, .17, z); this.root.add(p1);
    const p2 = new THREE.Mesh(new THREE.PlaneGeometry(68, 6), pathMat);
    p2.rotation.x = -Math.PI / 2; p2.position.set(x, .171, z); this.root.add(p2);
    // pond
    const pond = new THREE.Mesh(new THREE.CircleGeometry(11, 32), new THREE.MeshStandardMaterial({ color: 0x1b4d63, roughness: .15, metalness: .5, transparent: true, opacity: .9 }));
    pond.rotation.x = -Math.PI / 2; pond.position.set(x - 14, .18, z + 15); this.root.add(pond);
    const fountain = new THREE.Group(); fountain.position.set(x + 15, .2, z - 14);
    const basin = new THREE.Mesh(new THREE.CylinderGeometry(4.2, 4.6, .8, 24), this.concreteMat); basin.position.y = .4; fountain.add(basin);
    const water = new THREE.Mesh(new THREE.CylinderGeometry(3.7, 3.7, .3, 24), new THREE.MeshStandardMaterial({ color: 0x4aa3c4, roughness: .12, metalness: .5 })); water.position.y = .82; fountain.add(water);
    const column = new THREE.Mesh(new THREE.CylinderGeometry(.4, .6, 2.4, 12), this.whiteMat); column.position.y = 1.9; fountain.add(column);
    this.root.add(fountain);
    for (let i = 0; i < 12; i++) {
      const a = rng() * TAU, r = 8 + rng() * 25;
      if (Math.abs(Math.cos(a) * r) < 5 || Math.abs(Math.sin(a) * r) < 5) continue;
      this.tree(x + Math.cos(a) * r, z + Math.sin(a) * r, .9 + rng() * .7);
    }
    for (let i = 0; i < 7; i++) {
      const a = rng() * TAU, r = 10 + rng() * 18;
      this.bench(x + Math.cos(a) * r, z + Math.sin(a) * r, -a + Math.PI / 2);
    }
    const stage = new THREE.Mesh(new THREE.BoxGeometry(12, .7, 7), this.woodMat);
    stage.position.set(x + 20, .55, z + 22); stage.castShadow = true; this.root.add(stage);
    const backdrop = new THREE.Mesh(new THREE.BoxGeometry(12, 4, .4), this.darkMat);
    backdrop.position.set(x + 20, 2.6, z + 25); this.root.add(backdrop);
    this.addPOI('park', 'Aurora Park', x, z, 30, { icon: 'park' });
  }

  tree(x, z, scale = 1) {
    if (!this._treeGeo) {
      this._treeGeo = {
        trunk: new THREE.CylinderGeometry(.22, .32, 3.2, 6),
        leaves: new THREE.IcosahedronGeometry(2.1, 0),
      };
      this._treeMat = new THREE.MeshStandardMaterial({ color: 0x2f4a26, roughness: 1 });
      this._trunkMat = new THREE.MeshStandardMaterial({ color: 0x4a3725, roughness: 1 });
      this._trees = [];
    }
    this._trees.push({ x, z, scale });
  }

  bench(x, z, rot) {
    if (!this._benches) this._benches = [];
    this._benches.push({ x, z, rot });
  }

  addPOI(type, name, x, z, radius, extra = {}) {
    const poi = { type, name, x, z, radius, ...extra };
    this.pois.push(poi);
    return poi;
  }

  addSign(text, x, y, z, rotY, color = '#0b3a5a') {
    const mat = new THREE.MeshBasicMaterial({ map: signTexture(text, color, '#eaf6ff'), transparent: true });
    const m = new THREE.Mesh(new THREE.PlaneGeometry(6, 3), mat);
    m.position.set(x, y, z); m.rotation.y = rotY; this.root.add(m);
    return m;
  }

  buildHospital(block) {
    const { x, z } = block;
    this.addBuilding(x, z, 38, 30, 28, 'midrise', 3);
    this.addRoofDetails(x, z, 38, 30, 28.2, makeRng(99));
    // red cross
    const mat = new THREE.MeshBasicMaterial({ color: 0xff5b6c });
    const c1 = new THREE.Mesh(new THREE.BoxGeometry(4, 12, .3), mat); c1.position.set(x, 22, z + 15.2); this.root.add(c1);
    const c2 = new THREE.Mesh(new THREE.BoxGeometry(12, 4, .3), mat); c2.position.set(x, 22, z + 15.2); this.root.add(c2);
    const sign = this.addSign('HOSPITAL', x, 13, z + 15.3, 0, '#5c1020');
    const helipad = new THREE.Mesh(new THREE.CylinderGeometry(9, 9, .2, 24), new THREE.MeshStandardMaterial({ color: 0x3a3f42, roughness: .9 }));
    helipad.position.set(x + 24, .25, z + 20); this.root.add(helipad);
    const hMat = new THREE.MeshBasicMaterial({ color: 0xe8eef2 });
    const h1 = new THREE.Mesh(new THREE.BoxGeometry(1, .03, 5), hMat); h1.position.set(x + 24, .38, z + 20); this.root.add(h1);
    const h2 = new THREE.Mesh(new THREE.BoxGeometry(3, .03, 1), hMat); h2.position.set(x + 24, .38, z + 20); this.root.add(h2);
    this.helipad = new THREE.Vector3(x + 24, .4, z + 20);
    this.addPOI('hospital', 'Nova General Hospital', x, z, 32, { icon: 'hospital' });
  }

  buildPolice(block) {
    const { x, z } = block;
    this.addBuilding(x, z, 32, 26, 18, 'midrise', 3, { roofMat: this.roofMatDark });
    this.addRoofDetails(x, z, 32, 26, 18.2, makeRng(33));
    this.addSign('POLICE', x, 10.5, z + 13.2, 0, '#0b2a5a');
    const parking = new THREE.Mesh(new THREE.PlaneGeometry(26, 12), new THREE.MeshStandardMaterial({ color: 0x2c3034, roughness: 1 }));
    parking.rotation.x = -Math.PI / 2; parking.position.set(x, .17, z + 20); this.root.add(parking);
    this.addPOI('police', 'NCPD Central Precinct', x, z, 30, { icon: 'police' });
  }

  buildFireStation(block) {
    const { x, z } = block;
    this.addBuilding(x, z, 30, 24, 11, 'industrial', 0, { roofMat: this.roofMatDark });
    this.addSign('FIRE DEPT', x, 8, z + 12.2, 0, '#5c1015');
    const doorMat = new THREE.MeshStandardMaterial({ color: 0x7a1e24, roughness: .8 });
    for (let i = -1; i <= 1; i++) {
      const door = new THREE.Mesh(new THREE.BoxGeometry(7, 7, .3), doorMat);
      door.position.set(x + i * 8, 3.7, z + 12.2); this.root.add(door);
    }
    this.addPOI('fire', 'Nova Fire Station 3', x, z, 28, { icon: 'fire' });
  }

  buildGarage(block) {
    const { x, z } = block;
    this.addBuilding(x, z, 30, 24, 9, 'industrial', 2, { roofMat: this.roofMatDark });
    this.addSign('AUTO GARAGE', x, 6.8, z + 12.2, 0, '#4a2b05');
    this.addPOI('garage', 'Apex Auto Garage', x, z - 2, 22, { icon: 'garage' });
  }

  buildDealership(block) {
    const { x, z } = block;
    // glass showroom
    this.addBuilding(x - 8, z, 34, 22, 8, 'downtown', 1, { roofMat: this.roofMatDark });
    const sign = this.addSign('NOVA MOTORS', x - 8, 10, z + 11.5, 0, '#1d4e7a');
    const lot = new THREE.Mesh(new THREE.PlaneGeometry(60, 22), new THREE.MeshStandardMaterial({ color: 0x30343a, roughness: .9 }));
    lot.rotation.x = -Math.PI / 2; lot.position.set(x, .17, z + 24); this.root.add(lot);
    this.addPOI('dealership', 'Nova Motors Dealership', x - 8, z + 8, 22, { icon: 'dealer' });
  }

  buildApartment(block) {
    const { x, z } = block;
    this.addBuilding(x, z - 4, 34, 26, 26, 'midrise', 0);
    this.addRoofDetails(x, z - 4, 34, 26, 26.2, makeRng(17));
    this.addBalconies(x, z - 4, 34, 26, 26, makeRng(19));
    this.addSign('THE HALE', x, 5.4, z + 10.5, 0, '#2b251e');
    this.addPOI('apartment', 'The Hale Apartments', x, z + 12, 18, { icon: 'home' });
  }

  buildShop(block) {
    const { x, z } = block;
    this.addBuilding(x, z, 28, 20, 7, 'midrise', 2);
    this.addSign('MARKET', x, 5, z + 10.2, 0, '#1b4a39');
    this.addPOI('shop', 'Corner Market', x, z + 12, 16, { icon: 'shop' });
  }

  buildOffice(block) {
    const { x, z } = block;
    this.addBuilding(x, z, 40, 30, 42, 'downtown', 0);
    this.addBuilding(x, z, 28, 20, 58, 'downtown', 1, { base: 42 });
    this.addRoofDetails(x, z, 28, 20, 100.2, makeRng(5), 'tower');
    this.addPOI('office', 'Meridian Tower', x, z, 20, { icon: 'office' });
  }

  buildHotel(block) {
    const { x, z } = block;
    this.addBuilding(x, z, 36, 28, 46, 'midrise', 3);
    this.addBalconies(x, z, 36, 28, 46, makeRng(21));
    this.addRoofDetails(x, z, 36, 28, 46.2, makeRng(22), 'tower');
    this.addSign('HOTEL AURORA', x, 5.5, z + 14.5, 0, '#2b3c52');
    this.addPOI('hotel', 'Hotel Aurora', x, z + 16, 18, { icon: 'hotel' });
  }

  buildFactory(block, rng) {
    const { x, z } = block;
    this.addBuilding(x, z, 52, 34, 15, 'industrial', 2, { roofMat: this.roofMatDark });
    for (let i = -1; i <= 1; i += 2) {
      const chim = new THREE.Mesh(new THREE.CylinderGeometry(1.1, 1.5, 34, 12), new THREE.MeshStandardMaterial({ color: 0x8c8a83, roughness: .95 }));
      chim.position.set(x + i * 17, 17, z - 10); chim.castShadow = true; this.root.add(chim);
    }
    this.factorySmokePos = new THREE.Vector3(x, 34, z - 10);
    this.addPOI('factory', 'Northgate Works', x, z, 24, { icon: 'factory' });
  }

  buildSignals() {
    const nodes = [];
    for (let i = 0; i < GRID; i++) for (let j = 0; j < GRID; j++) {
      const central = Math.abs(i - 4) <= 3 && Math.abs(j - 4) <= 3;
      nodes.push({ i, j, x: NODE_POS(i), z: NODE_POS(j), hasLights: central });
    }
    this.nodes = nodes;
    this.nodeGrid = [];
    for (let i = 0; i < GRID; i++) { this.nodeGrid[i] = []; for (let j = 0; j < GRID; j++) this.nodeGrid[i][j] = nodes.find(n => n.i === i && n.j === j); }

    const poleGeo = new THREE.CylinderGeometry(.12, .16, 4.8, 6);
    const poleMat = new THREE.MeshStandardMaterial({ color: 0x3a3f44, roughness: .8, metalness: .4 });
    const lampGeo = new THREE.SphereGeometry(.19, 8, 6);
    const lampMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    const lampPositions = [];
    const poles = [];
    const armGeo = new THREE.BoxGeometry(2.2, .12, .12);
    const arms = [];
    this.signalLampData = [];
    for (const n of nodes) {
      if (!n.hasLights) continue;
      const corners = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
      for (const [sx, sz] of corners) {
        const px = n.x + sx * (HALF_ROAD + 1.3), pz = n.z + sz * (HALF_ROAD + 1.3);
        poles.push([px, 2.4, pz]);
        arms.push([px + (sx > 0 ? -1 : 1) * 1.1, 4.35, pz, sx > 0 ? 0 : Math.PI]);
        for (let k = 0; k < 3; k++) {
          const ly = 4.75 - k * .34;
          lampPositions.push([px + (sx > 0 ? -1.05 : 1.05), ly, pz]);
          this.signalLampData.push({ node: n, axis: sz === 0 ? 'x' : 'z', slot: k, index: lampPositions.length - 1 });
        }
      }
    }
    const poleMesh = new THREE.InstancedMesh(poleGeo, poleMat, poles.length);
    const tmp = new THREE.Object3D();
    poles.forEach(([x, y, z], i) => { tmp.position.set(x, y, z); tmp.updateMatrix(); poleMesh.setMatrixAt(i, tmp.matrix); });
    this.root.add(poleMesh);
    const armMesh = new THREE.InstancedMesh(armGeo, poleMat, arms.length);
    arms.forEach(([x, y, z, r], i) => { tmp.position.set(x, y, z); tmp.rotation.set(0, r, 0); tmp.updateMatrix(); armMesh.setMatrixAt(i, tmp.matrix); });
    this.root.add(armMesh);
    this.signalLampMesh = new THREE.InstancedMesh(lampGeo, lampMat, lampPositions.length);
    this.signalLampMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(lampPositions.length * 3), 3);
    lampPositions.forEach(([x, y, z], i) => {
      tmp.position.set(x, y, z); tmp.rotation.set(0, 0, 0); tmp.updateMatrix();
      this.signalLampMesh.setMatrixAt(i, tmp.matrix);
      this.signalLampMesh.setColorAt(i, new THREE.Color(0x111111));
    });
    this.root.add(this.signalLampMesh);
    this.signalNodes = nodes;
  }

  signalState(node, axis, time) {
    if (!node.hasLights) return 'green';
    const t = (time + (node.i * 1.7 + node.j * 2.3)) % 26;
    if (axis === 'x') {
      if (t < 9) return 'green';
      if (t < 11) return 'yellow';
      if (t < 24) return 'red';
      return 'yellow';
    }
    if (t < 11) return 'red';
    if (t < 15) return 'green';
    if (t < 24) return 'red';
    if (t < 26) return 'green';
    return 'red';
  }

  updateSignals(elapsed) {
    const colors = { red: new THREE.Color(0xff2b3e), yellow: new THREE.Color(0xffb12b), green: new THREE.Color(0x2bff9a), off: new THREE.Color(0x101316) };
    for (const data of this.signalLampData) {
      const state = this.signalState(data.node, data.axis, elapsed);
      const active = state === 'red' ? 0 : state === 'yellow' ? 1 : 2;
      let c;
      if (data.slot === active) c = colors[state];
      else c = colors.off;
      this.signalLampMesh.setColorAt(data.index, c);
    }
    this.signalLampMesh.instanceColor.needsUpdate = true;
  }

  buildParkingSpots(rng) {
    for (let i = 0; i < GRID; i++) {
      for (let j = 0; j < 8; j++) {
        const z1 = NODE_POS(j) + 18 + rng() * 50;
        this.parkingSpots.push({ x: NODE_POS(i) + HALF_ROAD + 2.8, z: z1, heading: -Math.PI / 2 });
        this.parkingSpots.push({ x: NODE_POS(i) - HALF_ROAD - 2.8, z: z1, heading: Math.PI / 2 });
        const x1 = NODE_POS(j) + 18 + rng() * 50;
        this.parkingSpots.push({ x: x1, z: NODE_POS(i) + HALF_ROAD + 2.8, heading: Math.PI });
        this.parkingSpots.push({ x: x1, z: NODE_POS(i) - HALF_ROAD - 2.8, heading: 0 });
      }
    }
  }

  finalizeProps() {
    // instanced trees / benches accumulated during block generation
    if (this._trees && this._trees.length) {
      const n = this._trees.length;
      const trunk = new THREE.InstancedMesh(this._treeGeo.trunk, this._trunkMat, n);
      const leaves = new THREE.InstancedMesh(this._treeGeo.leaves, this._treeMat, n);
      const tmp = new THREE.Object3D();
      this._trees.forEach((t, i) => {
        tmp.position.set(t.x, 1.6 * t.scale + .15, t.z);
        tmp.scale.setScalar(t.scale); tmp.updateMatrix(); trunk.setMatrixAt(i, tmp.matrix);
        tmp.position.set(t.x, 4.3 * t.scale + .15, t.z);
        tmp.scale.set(t.scale * (1 + Math.random() * .3), t.scale * (1 + Math.random() * .4), t.scale * (1 + Math.random() * .3));
        tmp.rotation.set(Math.random(), Math.random() * 3, Math.random()); tmp.updateMatrix();
        leaves.setMatrixAt(i, tmp.matrix);
      });
      trunk.castShadow = true; leaves.castShadow = true;
      this.root.add(trunk, leaves);
    }
    if (this._benches && this._benches.length) {
      const benchGeo = new THREE.BoxGeometry(2.2, .16, .65);
      const backGeo = new THREE.BoxGeometry(2.2, .5, .12);
      const legGeo = new THREE.BoxGeometry(.14, .5, .55);
      const bm = new THREE.InstancedMesh(benchGeo, this.woodMat, this._benches.length);
      const bbm = new THREE.InstancedMesh(backGeo, this.woodMat, this._benches.length);
      const lm = new THREE.InstancedMesh(legGeo, this.metalMat, this._benches.length * 2);
      const tmp = new THREE.Object3D();
      this._benches.forEach((b, i) => {
        tmp.position.set(b.x, .72, b.z); tmp.rotation.set(0, b.rot, 0); tmp.updateMatrix(); bm.setMatrixAt(i, tmp.matrix);
        tmp.position.set(b.x - Math.sin(b.rot) * .26, 1.0, b.z - Math.cos(b.rot) * .26); tmp.updateMatrix(); bbm.setMatrixAt(i, tmp.matrix);
        tmp.position.set(b.x - Math.cos(b.rot) * .8, .38, b.z + Math.sin(b.rot) * .8); tmp.updateMatrix(); lm.setMatrixAt(i * 2, tmp.matrix);
        tmp.position.set(b.x + Math.cos(b.rot) * .8, .38, b.z + Math.sin(b.rot) * .8); tmp.updateMatrix(); lm.setMatrixAt(i * 2 + 1, tmp.matrix);
      });
      this.root.add(bm, bbm, lm);
    }
  }

  updateLighting(hour, weather, dt) {
    this.hour = hour;
    const day = Math.max(0, Math.sin((hour - 6) / 24 * TAU));
    const night = clamp(1 - Math.max(0, Math.sin((hour - 5.5) / 24 * TAU)) * 2.2, 0, 1);
    this.night = night;
    this.weather = weather;
    const storm = weather === 'storm' ? 1 : weather === 'rain' ? .7 : weather === 'snow' ? .55 : 0;
    const dim = 1 - storm * .35;
    if (this.sun) {
      const sunAngle = (hour / 24) * TAU - Math.PI / 2;
      this.sun.position.set(Math.cos(sunAngle) * 700, Math.sin(sunAngle) * 700, 260);
      this.sun.intensity = clamp(Math.sin((hour - 5.8) / 12.4 * Math.PI) * 2.6, 0, 2.6) * dim;
      this.sun.color.setHSL(0.09 + day * .02, .45, .55 + day * .25);
    }
    this.hemi.intensity = lerp(0.2, 0.7, day) * dim;
    this.ambient.intensity = lerp(0.18, 0.32, day);
    const glow = night * 1.9 + (storm > 0 ? .15 : 0);
    for (const m of this.facadeMaterials) m.emissiveIntensity = 0.015 + glow * 0.95;
    if (this.lampGlow) {
      this.lampGlow.material.opacity = 0.22 + night * 0.78;
      this.lampGlow.material.size = 6 + night * 2;
    }
    if (this.crownMat) this.crownMat.emissiveIntensity = .2 + night * 2.4;
    if (this.sky) {
      this.sky.material.uniforms.night.value = night;
      this.sky.material.uniforms.storm.value = storm;
      this.sky.material.uniforms.sunDir.value.copy(this.sun.position).normalize();
    }
    if (this.stars) this.stars.material.opacity = clamp(night * 1.1 - .15, 0, .95);
    if (this.water) this.water.material.uniforms.night.value = night;
    if (this.moon) this.moon.material.opacity = night * .95;
    if (this.cloudSpriteMat) this.cloudSpriteMat.color.setScalar(lerp(1.1, .18, night) * (1 - storm * .25));
    document.body.dataset.night = night > .55 ? '1' : '0';
  }

  update(dt, elapsed, playerPos) {
    this.updateSignals(elapsed);
    if (this.water) {
      this.water.material.uniforms.time.value = elapsed;
    }
    for (const c of this.clouds) {
      c.position.x += c.userData.speed * dt;
      if (c.position.x > 900) c.position.x = -900;
      c.position.z += c.userData.speed * dt * .1;
      if (c.position.z > 700) c.position.z = -700;
    }
    if (this.lampGlow) this.lampGlow.rotation.y += 0;
    if (this.stars) this.stars.rotation.y = elapsed * .002;
    for (const a of this.animated) {
      if (a.type === 'beacon') a.mesh.material = this.warmMat;
    }
    if (this.monorail) this.monorail.update(dt, elapsed);
    if (this.rail) this.rail.update(dt, elapsed);
    if (this.highwayCars.length) {
      for (const c of this.highwayCars) {
        c.position.z += c.userData.speed * dt;
        if (c.position.z > 700) { c.position.z = -700; c.position.x = c.userData.lane; }
      }
    }
    this.updateFactorySmoke(dt, elapsed);
    this.updateFireflies(dt, elapsed);
  }

  updateFactorySmoke(dt, elapsed) {
    if (!this.factorySmokePos || !this.smokeParticles) return;
    const p = this.smokeParticles;
    p.userData.t = (p.userData.t || 0) + dt;
    const pos = p.geometry.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      let y = pos.getY(i) + dt * (2.2 + (i % 5) * .3);
      let x = pos.getX(i) + dt * .55;
      let z = pos.getZ(i) + Math.sin(elapsed * .6 + i) * dt * .2;
      if (y > 50) { y = 0; x = this.factorySmokePos.x + (Math.random() - .5) * 2; z = this.factorySmokePos.z + (Math.random() - .5) * 2; }
      pos.setXYZ(i, x, y, z);
    }
    pos.needsUpdate = true;
  }

  updateFireflies(dt, elapsed) {
    if (!this.fireflyPoints) return;
    this.fireflyPoints.material.opacity = (this.night > .5 ? .8 : 0) * (this.weather === 'clear' ? 1 : .15);
    this.fireflyPoints.position.y = .6 + Math.sin(elapsed * .8) * .1;
  }

  districtAt(x, z) {
    const bi = Math.floor((x + CITY_EXTENT) / SPACING);
    const bj = Math.floor((z + CITY_EXTENT) / SPACING);
    const b = this.blocks.find(b => b.bi === bi && b.bj === bj);
    if (b) return this.districtName(b.district);
    if (z > 420) return 'NOVA HARBOR';
    if (x > 420) return 'NOVA AIRFIELD';
    if (z < -400 || x < -400) return 'OUTSKIRTS';
    return 'NOVA CITY';
  }

  districtName(d) {
    return {
      downtown: 'DOWNTOWN', midtown: 'MIDTOWN', industrial: 'INDUSTRIAL', suburb: 'PINE HILLS',
      waterfront: 'HARBORFRONT', residential: 'WEST END', park: 'AURORA PARK', airport: 'AIRFIELD',
    }[d] || 'NOVA CITY';
  }

  collideCircle(x, z, r) {
    let hit = null;
    for (const b of this.spatial.query(x, z, r + 2)) {
      if (b.type !== 'building') continue;
      const cx = clamp(x, b.minX, b.maxX), cz = clamp(z, b.minZ, b.maxZ);
      const dx = x - cx, dz = z - cz;
      const d2 = dx * dx + dz * dz;
      if (d2 < r * r) {
        const d = Math.sqrt(d2) || 0.0001;
        hit = { nx: dx / d, nz: dz / d, pen: r - d, box: b };
        break;
      }
    }
    return hit;
  }

  nearestPOI(x, z, radius = 999, types = null) {
    let best = null, bd = radius;
    for (const p of this.pois) {
      if (types && !types.includes(p.type)) continue;
      const d = Math.hypot(x - p.x, z - p.z);
      if (d < bd) { bd = d; best = p; }
    }
    return best ? { poi: best, dist: bd } : null;
  }

  nearestNode(x, z) {
    let best = null, bd = Infinity;
    for (const n of this.nodes) {
      const d = Math.hypot(x - n.x, z - n.z);
      if (d < bd) { bd = d; best = n; }
    }
    return best;
  }

  isOnRoad(x, z) {
    for (let i = 0; i < GRID; i++) {
      if (Math.abs(x - NODE_POS(i)) < HALF_ROAD) return true;
      if (Math.abs(z - NODE_POS(i)) < HALF_ROAD) return true;
    }
    return false;
  }
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { clamp, rand, pick, chance, TAU, makeRng, glowTexture, smokeTexture, starTexture } from './utils.js';
import { glowTexture as glowTex, smokeTexture as smokeTex, starTexture as starTex, billboardTexture, signTexture } from './textures.js';
import { NODE_POS, SPACING, HALF_ROAD, CITY_EXTENT, GRID } from './city.js';

export function buildSky(city) {
  const scene = city.scene;
  const skyGeo = new THREE.SphereGeometry(1900, 32, 20);
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false,
    uniforms: {
      topColor: { value: new THREE.Color(0x17476e) },
      bottomColor: { value: new THREE.Color(0xe6b48b) },
      night: { value: 0 }, storm: { value: 0 },
      sunDir: { value: new THREE.Vector3(0, 1, 0) },
    },
    vertexShader: `varying vec3 vWorld; void main(){ vWorld = (modelMatrix * vec4(position,1.0)).xyz; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
    fragmentShader: `
      uniform vec3 topColor; uniform vec3 bottomColor; uniform vec3 sunDir; uniform float night; uniform float storm;
      varying vec3 vWorld;
      void main(){
        vec3 d = normalize(vWorld);
        float h = clamp(d.y * 1.4 + .12, 0., 1.);
        vec3 day = mix(bottomColor, topColor, pow(h, .55));
        vec3 dusk = mix(vec3(.16,.11,.19), vec3(.56,.26,.18), h);
        vec3 nightC = mix(vec3(.012,.025,.055), vec3(.004,.008,.02), h);
        vec3 col = mix(day, dusk, smoothstep(.72,.92,night)*.65);
        col = mix(col, nightC, night);
        col = mix(col, vec3(.17,.19,.21), storm*.55);
        float sd = max(dot(d, normalize(sunDir)), 0.);
        col += vec3(1.,.7,.38) * pow(sd, 220.) * (1.-night) * 2.2;
        col += vec3(1.,.6,.3) * pow(sd, 8.) * .16 * (1.-night) * (1.-storm*.5);
        gl_FragColor = vec4(col, 1.);
      }`,
  });
  const sky = new THREE.Mesh(skyGeo, skyMat);
  sky.frustumCulled = false;
  scene.add(sky);
  city.sky = sky;

  const sun = new THREE.DirectionalLight(0xffe7c4, 2.4);
  sun.position.set(300, 500, 200);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.near = 10;
  sun.shadow.camera.far = 1500;
  sun.shadow.camera.left = -280; sun.shadow.camera.right = 280;
  sun.shadow.camera.top = 280; sun.shadow.camera.bottom = -280;
  sun.shadow.bias = -0.0012;
  sun.shadow.normalBias = 0.6;
  scene.add(sun);
  scene.add(sun.target);
  city.sun = sun;

  const hemi = new THREE.HemisphereLight(0x9dc8ff, 0x3b4230, 0.6);
  scene.add(hemi); city.hemi = hemi;
  const amb = new THREE.AmbientLight(0xb8d4ff, 0.24);
  scene.add(amb); city.ambient = amb;

  // moon
  const moonMat = new THREE.SpriteMaterial({ map: glowTex(), color: 0xcfe4ff, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending });
  const moon = new THREE.Sprite(moonMat);
  moon.scale.set(70, 70, 1); moon.position.set(-500, 900, -600);
  scene.add(moon); city.moon = moon;

  // stars
  const starGeo = new THREE.BufferGeometry();
  const sp = new Float32Array(1400 * 3);
  for (let i = 0; i < 1400; i++) {
    const a = Math.random() * TAU, b = Math.acos(2 * Math.random() - 1);
    const r = 1500;
    sp[i * 3] = Math.sin(b) * Math.cos(a) * r;
    sp[i * 3 + 1] = Math.abs(Math.cos(b)) * r * .8 + 120;
    sp[i * 3 + 2] = Math.sin(b) * Math.sin(a) * r;
  }
  starGeo.setAttribute('position', new THREE.BufferAttribute(sp, 3));
  const starMat = new THREE.PointsMaterial({ map: starTex(), size: 6, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true });
  const stars = new THREE.Points(starGeo, starMat);
  scene.add(stars); city.stars = stars;

  // clouds
  const cloudMat = new THREE.SpriteMaterial({ map: makeCloud(), color: 0xf2f6ff, transparent: true, opacity: .85, depthWrite: false });
  city.cloudSpriteMat = cloudMat;
  for (let i = 0; i < 30; i++) {
    const s = new THREE.Sprite(cloudMat);
    const sc = 90 + Math.random() * 180;
    s.scale.set(sc * 2.1, sc * .8, 1);
    s.position.set(rand(-900, 900), rand(130, 220), rand(-900, 900));
    s.userData.speed = rand(1.5, 4.5);
    scene.add(s); city.clouds.push(s);
  }
}

function makeCloud() {
  const c = document.createElement('canvas'); c.width = 256; c.height = 128;
  const ctx = c.getContext('2d');
  for (let i = 0; i < 34; i++) {
    const x = 30 + Math.random() * 196, y = 64 + (Math.random() - .5) * 40, r = 12 + Math.random() * 30;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(255,255,255,.5)');
    g.addColorStop(.55, 'rgba(240,246,255,.22)');
    g.addColorStop(1, 'rgba(240,246,255,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
  }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}

export function buildProps(city, rng) {
  const root = city.root;
  const tmp = new THREE.Object3D();

  // street lights
  const poleGeo = new THREE.CylinderGeometry(.09, .14, 5.6, 6);
  const poleMat = new THREE.MeshStandardMaterial({ color: 0x30363b, roughness: .7, metalness: .5 });
  const armGeo = new THREE.BoxGeometry(2.4, .1, .1);
  const headGeo = new THREE.BoxGeometry(1.1, .18, .4);
  const headMat = new THREE.MeshStandardMaterial({ color: 0xffe6b8, emissive: 0xffcf8a, emissiveIntensity: 2.2, roughness: .4 });
  const lampPositions = [];
  for (let i = 0; i < GRID; i++) {
    const p = NODE_POS(i);
    for (let t = -CITY_EXTENT + 12; t <= CITY_EXTENT - 12; t += 44) {
      for (const s of [-1, 1]) {
        lampPositions.push({ pole: [p + s * (HALF_ROAD + 3.4), 2.85, t], arm: [p + s * (HALF_ROAD + 2.4), 5.5, t], armR: 0, head: [p + s * (HALF_ROAD + 1.6), 5.45, t] });
        lampPositions.push({ pole: [t, 2.85, p + s * (HALF_ROAD + 3.4)], arm: [t, 5.5, p + s * (HALF_ROAD + 2.4)], armR: Math.PI / 2, head: [t, 5.45, p + s * (HALF_ROAD + 1.6)] });
      }
    }
  }
  const poles = new THREE.InstancedMesh(poleGeo, poleMat, lampPositions.length);
  const arms = new THREE.InstancedMesh(armGeo, poleMat, lampPositions.length);
  const heads = new THREE.InstancedMesh(headGeo, headMat, lampPositions.length);
  lampPositions.forEach((l, i) => {
    tmp.position.set(...l.pole); tmp.rotation.set(0, 0, 0); tmp.updateMatrix(); poles.setMatrixAt(i, tmp.matrix);
    tmp.position.set(...l.arm); tmp.rotation.set(0, l.armR, 0); tmp.updateMatrix(); arms.setMatrixAt(i, tmp.matrix);
    tmp.position.set(...l.head); tmp.rotation.set(0, 0, 0); tmp.updateMatrix(); heads.setMatrixAt(i, tmp.matrix);
  });
  poles.castShadow = true;
  root.add(poles, arms, heads);

  const glowGeo = new THREE.BufferGeometry();
  const gp = new Float32Array(lampPositions.length * 3);
  lampPositions.forEach((l, i) => { gp[i * 3] = l.head[0]; gp[i * 3 + 1] = l.head[1] - .1; gp[i * 3 + 2] = l.head[2]; });
  glowGeo.setAttribute('position', new THREE.BufferAttribute(gp, 3));
  const glowMat = new THREE.PointsMaterial({ map: glowTex(), color: 0xffc57c, size: 6, transparent: true, opacity: .35, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true });
  const glows = new THREE.Points(glowGeo, glowMat);
  glows.frustumCulled = false;
  root.add(glows);
  city.lampGlow = glows;

  // hydrants
  const hydGeo = new THREE.CylinderGeometry(.16, .2, .6, 8);
  const hydMat = new THREE.MeshStandardMaterial({ color: 0xb03a2e, roughness: .7 });
  const hyds = new THREE.InstancedMesh(hydGeo, hydMat, 44);
  for (let i = 0; i < 44; i++) {
    const n = Math.floor(Math.random() * GRID), p = NODE_POS(n);
    const along = rand(-CITY_EXTENT + 20, CITY_EXTENT - 20);
    const side = Math.random() > .5 ? 1 : -1;
    tmp.position.set(Math.random() > .5 ? p + side * 10 : along, .45, Math.random() > .5 ? along : p + side * 10);
    tmp.updateMatrix(); hyds.setMatrixAt(i, tmp.matrix);
  }
  root.add(hyds);

  // bins
  const binGeo = new THREE.CylinderGeometry(.32, .26, .9, 8);
  const binMat = new THREE.MeshStandardMaterial({ color: 0x37424a, roughness: .8 });
  const bins = new THREE.InstancedMesh(binGeo, binMat, 55);
  for (let i = 0; i < 55; i++) {
    const n = Math.floor(Math.random() * GRID), p = NODE_POS(n);
    const along = rand(-CITY_EXTENT + 20, CITY_EXTENT - 20);
    const side = Math.random() > .5 ? 1 : -1;
    tmp.position.set(Math.random() > .5 ? p + side * 10.2 : along, .6, Math.random() > .5 ? along : p + side * 10.2);
    tmp.updateMatrix(); bins.setMatrixAt(i, tmp.matrix);
  }
  root.add(bins);

  // bus shelters
  const busSpots = [
    [-260, -192, Math.PI / 2], [132, -96, Math.PI / 2], [96, 180, 0], [-96, 96, 0],
    [260, 48, Math.PI / 2], [-192, 260, 0], [288, -240, Math.PI / 2], [-48, -300, 0],
  ];
  for (const [x, z, r] of busSpots) {
    city.busStops.push({ x, z });
    const g = new THREE.Group(); g.position.set(x, .15, z); g.rotation.y = r;
    const roof = new THREE.Mesh(new THREE.BoxGeometry(5.6, .18, 2.2), new THREE.MeshStandardMaterial({ color: 0x2e3740, roughness: .7, metalness: .4 }));
    roof.position.y = 2.7; g.add(roof);
    const glass = new THREE.Mesh(new THREE.BoxGeometry(5.2, 2.5, .08), new THREE.MeshStandardMaterial({ color: 0x9fc6dd, transparent: true, opacity: .28, roughness: .05, metalness: .3 }));
    glass.position.set(0, 1.4, -1.0); g.add(glass);
    for (const sx of [-2.6, 2.6]) {
      const post = new THREE.Mesh(new THREE.BoxGeometry(.1, 2.7, .1), city.metalMat);
      post.position.set(sx, 1.35, -1.0); g.add(post);
    }
    const seat = new THREE.Mesh(new THREE.BoxGeometry(4.2, .16, .55), city.woodMat); seat.position.set(0, .58, -.7); g.add(seat);
    const sign = new THREE.Mesh(new THREE.PlaneGeometry(.9, .9), new THREE.MeshBasicMaterial({ map: signTexture('BUS', '#1c5a8a', '#eef8ff'), transparent: true }));
    sign.position.set(2.9, 1.8, 0); g.add(sign);
    root.add(g);
    city.busStops[city.busStops.length - 1].mesh = g;
  }

  // billboards around downtown
  const ads = [
    ['SOLARIS', 'clean energy · bright future', '#062c46', '#1188b8'],
    ['VOLT', 'the city runs electric', '#2b0a3d', '#8a37b8'],
    ['AURORA', 'live above it all', '#3c1a08', '#c86a23'],
    ['NOVA AIR', 'fly beyond the skyline', '#082c33', '#16a6a0'],
  ];
  ads.forEach((a, i) => {
    const angle = i * Math.PI / 2 + .4;
    const x = Math.cos(angle) * 190, z = Math.sin(angle) * 190;
    const mat = new THREE.MeshBasicMaterial({ map: billboardTexture(a[0], a[1], a[2], a[3]) });
    const b = new THREE.Mesh(new THREE.PlaneGeometry(28, 14), mat);
    b.position.set(x, 42 + i * 3, z); b.lookAt(0, 30, 0); root.add(b);
    for (const s of [-1, 1]) {
      const leg = new THREE.Mesh(new THREE.BoxGeometry(.5, 8, .5), city.metalMat);
      leg.position.set(x + s * 8, 38, z); root.add(leg);
    }
  });

  // roadside trees on residential edges
  for (let bi = 0; bi < 8; bi++) {
    for (let bj = 0; bj < 8; bj++) {
      const d = city.blocks.find(b => b.bi === bi && b.bj === bj);
      if (!d || !['suburb', 'residential', 'waterfront', 'park'].includes(d.district)) continue;
      for (let k = 0; k < 4; k++) {
        const edge = Math.floor(Math.random() * 4);
        const off = rand(-30, 30);
        if (edge === 0) city.tree(d.x + off, d.z - 35.6, rand(.55, .9));
        if (edge === 1) city.tree(d.x + off, d.z + 35.6, rand(.55, .9));
        if (edge === 2) city.tree(d.x - 35.6, d.z + off, rand(.55, .9));
        if (edge === 3) city.tree(d.x + 35.6, d.z + off, rand(.55, .9));
      }
    }
  }

  // fireflies in park
  const fg = new THREE.BufferGeometry();
  const fp = new Float32Array(120 * 3);
  for (let i = 0; i < 120; i++) { fp[i * 3] = -24 + rand(-25, 25); fp[i * 3 + 1] = rand(.6, 4); fp[i * 3 + 2] = -24 + rand(-25, 25); }
  fg.setAttribute('position', new THREE.BufferAttribute(fp, 3));
  const fm = new THREE.PointsMaterial({ color: 0xffe08a, size: .35, transparent: true, opacity: .7, map: glowTex(), blending: THREE.AdditiveBlending, depthWrite: false });
  const fireflies = new THREE.Points(fg, fm);
  root.add(fireflies); city.fireflyPoints = fireflies;

  // factory smoke
  if (city.factorySmokePos) {
    const sg = new THREE.BufferGeometry();
    const sp = new Float32Array(70 * 3);
    for (let i = 0; i < 70; i++) {
      sp[i * 3] = city.factorySmokePos.x + rand(-2, 2);
      sp[i * 3 + 1] = rand(0, 48);
      sp[i * 3 + 2] = city.factorySmokePos.z + rand(-2, 2);
    }
    sg.setAttribute('position', new THREE.BufferAttribute(sp, 3));
    const sm = new THREE.PointsMaterial({ map: smokeTex(), color: 0x8c8c8c, size: 10, transparent: true, opacity: .28, depthWrite: false });
    const smoke = new THREE.Points(sg, sm);
    smoke.frustumCulled = false;
    root.add(smoke); city.smokeParticles = smoke;
  }

  city.finalizeProps();
}

export function buildWaterfront(city, rng) {
  const root = city.root;
  // beach
  const beach = new THREE.Mesh(new THREE.PlaneGeometry(1700, 100), city.mats.sand);
  beach.rotation.x = -Math.PI / 2; beach.position.set(0, .05, 438); beach.receiveShadow = true; root.add(beach);
  // promenade
  const prom = new THREE.Mesh(new THREE.PlaneGeometry(1400, 12), city.mats.sidewalk);
  prom.rotation.x = -Math.PI / 2; prom.position.set(0, .12, 392); root.add(prom);
  // boardwalk rail
  const railMat = new THREE.MeshStandardMaterial({ color: 0x6d5a43, roughness: .9 });
  for (let x = -420; x <= 420; x += 16) {
    const post = new THREE.Mesh(new THREE.BoxGeometry(.16, 1.1, .16), railMat);
    post.position.set(x, .65, 398); root.add(post);
  }
  const topRail = new THREE.Mesh(new THREE.BoxGeometry(840, .1, .12), railMat);
  topRail.position.set(0, 1.15, 398); root.add(topRail);
  // palms
  for (let i = 0; i < 18; i++) {
    const x = -400 + i * 46 + rand(-8, 8), z = 404 + (i % 2) * 6;
    const g = new THREE.Group();
    const trunk = new THREE.Mesh(new THREE.CylinderGeometry(.18, .32, 7, 6), new THREE.MeshStandardMaterial({ color: 0x7a6247, roughness: 1 }));
    trunk.position.y = 3.5; g.add(trunk);
    for (let l = 0; l < 6; l++) {
      const leaf = new THREE.Mesh(new THREE.ConeGeometry(.8, 4.4, 5), new THREE.MeshStandardMaterial({ color: 0x2f5a32, roughness: 1 }));
      leaf.position.set(Math.cos(l / 6 * TAU) * 1.4, 7.2, Math.sin(l / 6 * TAU) * 1.4);
      leaf.rotation.set(Math.cos(l / 6 * TAU) * .9, 0, Math.sin(l / 6 * TAU) * .9 + .5);
      g.add(leaf);
    }
    g.position.set(x, .1, z); root.add(g);
  }

  // ocean shader
  const waterGeo = new THREE.PlaneGeometry(2600, 1300, 80, 40);
  const waterMat = new THREE.ShaderMaterial({
    uniforms: {
      time: { value: 0 }, night: { value: 0 },
      deep: { value: new THREE.Color(0x0a3b52) }, shallow: { value: new THREE.Color(0x2a8ca6) },
      sky: { value: new THREE.Color(0x9ec6dd) },
    },
    vertexShader: `
      uniform float time; varying vec3 vWorld; varying float vWave;
      void main(){
        vec3 p = position;
        float w = sin(p.x*.035 + time*.7)*.5 + sin(p.y*.06 - time*.9)*.3 + sin((p.x+p.y)*.11 + time*1.6)*.12;
        p.z += w; vWave = w;
        vec4 wp = modelMatrix * vec4(p,1.0);
        vWorld = wp.xyz; gl_Position = projectionMatrix * viewMatrix * wp;
      }`,
    fragmentShader: `
      uniform float time; uniform float night; uniform vec3 deep; uniform vec3 shallow; uniform vec3 sky;
      varying vec3 vWorld; varying float vWave;
      void main(){
        vec3 v = normalize(cameraPosition - vWorld);
        float fres = pow(1.0 - max(v.y, 0.0), 2.2);
        vec3 col = mix(deep, shallow, .35 + vWave*.18);
        col = mix(col, sky, fres*.55);
        float sparkle = pow(max(0., sin(vWorld.x*.6 + time*1.3) * sin(vWorld.z*.45 - time)) , 18.);
        col += vec3(.8,.9,1.)*sparkle*.35*(1.-night);
        col *= 1.0 - night*.58;
        gl_FragColor = vec4(col, 0.94);
      }`,
    transparent: true,
  });
  const water = new THREE.Mesh(waterGeo, waterMat);
  water.rotation.x = -Math.PI / 2;
  water.position.set(0, .02, 920);
  root.add(water); city.water = water;

  // shoreline foam
  const foam = new THREE.Mesh(new THREE.PlaneGeometry(1700, 3), new THREE.MeshBasicMaterial({ color: 0xe7f6ff, transparent: true, opacity: .5 }));
  foam.rotation.x = -Math.PI / 2; foam.position.set(0, .09, 486); root.add(foam);
  city.animated.push({ type: 'foam', mesh: foam });

  // marina
  const dockMat = new THREE.MeshStandardMaterial({ color: 0x7b5f41, roughness: .95 });
  for (let i = 0; i < 4; i++) {
    const dock = new THREE.Mesh(new THREE.BoxGeometry(4, .35, 26), dockMat);
    dock.position.set(300 + i * 13, .35, 452 + 8); root.add(dock);
  }
  const mainDock = new THREE.Mesh(new THREE.BoxGeometry(52, .4, 6), dockMat);
  mainDock.position.set(319, .4, 444); root.add(mainDock);
  const mSign = new THREE.Mesh(new THREE.PlaneGeometry(7, 2.4), new THREE.MeshBasicMaterial({ map: signTexture('MARINA', '#123a4a', '#d8f4ff'), transparent: true }));
  mSign.position.set(319, 2.6, 440); root.add(mSign);
  city.marina = { x: 319, z: 452 };
  city.addPOI('marina', 'Harbor Marina', 319, 442, 20, { icon: 'marina' });

  // beach umbrellas
  for (let i = 0; i < 14; i++) {
    const x = -380 + i * 55, z = 414 + (i % 3) * 8;
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(.05, .05, 2.6, 5), city.metalMat);
    pole.position.set(x, 1.35, z); root.add(pole);
    const top = new THREE.Mesh(new THREE.ConeGeometry(2, .6, 10), new THREE.MeshStandardMaterial({ color: pick([0xd96b5b, 0x4f8fa3, 0xe0b45c, 0x6d9e77]), roughness: .9, side: THREE.DoubleSide }));
    top.position.set(x, 2.7, z); root.add(top);
  }
}

export function buildTransit(city, rng) {
  const root = city.root;
  // --- monorail guideway loop ---
  const R = 250, Y = 14;
  const guideMat = new THREE.MeshStandardMaterial({ color: 0x8f9aa3, roughness: .4, metalness: .55 });
  const guideMat2 = new THREE.MeshStandardMaterial({ color: 0x4a5560, roughness: .5, metalness: .5 });
  const guide = new THREE.Group();
  const segs = [
    [0, -R, 2 * R, 3.2, 0], [0, R, 2 * R, 3.2, 0],
    [-R, 0, 3.2, 2 * R, 0], [R, 0, 3.2, 2 * R, 0],
  ];
  for (const [x, z, w, d] of segs) {
    const beam = new THREE.Mesh(new THREE.BoxGeometry(w, .9, d), guideMat);
    beam.position.set(x, Y, z); beam.castShadow = true; guide.add(beam);
    const rail = new THREE.Mesh(new THREE.BoxGeometry(w + .2, .16, d + .2), guideMat2);
    rail.position.set(x, Y + .52, z); guide.add(rail);
  }
  // corner curves approximated
  for (const [sx, sz] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) {
    const curve = new THREE.Mesh(new THREE.TorusGeometry(10, 1.5, 6, 18, Math.PI / 2), guideMat);
    curve.rotation.x = Math.PI / 2; curve.position.set(sx * (R - 10), Y, sz * (R - 10));
    curve.rotation.z = Math.atan2(sz, sx) - Math.PI / 4;
    guide.add(curve);
  }
  // pillars
  const pillarGeo = new THREE.CylinderGeometry(.75, .95, Y, 8);
  for (let x = -R; x <= R; x += 25) {
    for (const z of [-R, R]) {
      const p = new THREE.Mesh(pillarGeo, guideMat2);
      p.position.set(x, Y / 2, z); p.castShadow = true; guide.add(p);
    }
  }
  for (let z = -R + 25; z <= R - 25; z += 25) {
    for (const x of [-R, R]) {
      const p = new THREE.Mesh(pillarGeo, guideMat2);
      p.position.set(x, Y / 2, z); p.castShadow = true; guide.add(p);
    }
  }
  // stations (corners of loop midpoints)
  const stations = [
    { x: 0, z: -R, ang: 0, name: 'NORTH LOOP' },
    { x: R, z: 0, ang: Math.PI / 2, name: 'EAST GATE' },
    { x: 0, z: R, ang: Math.PI, name: 'HARBOR VIEW' },
    { x: -R, z: 0, ang: -Math.PI / 2, name: 'WEST END' },
  ];
  for (let i = 0; i < stations.length; i++) {
    const s = stations[i];
    const platform = new THREE.Mesh(new THREE.BoxGeometry(28, .6, 7), guideMat);
    platform.position.set(s.x + Math.cos(s.ang) * 0, Y - .9, s.z + 0); guide.add(platform);
    const canopy = new THREE.Mesh(new THREE.BoxGeometry(26, .25, 6), new THREE.MeshStandardMaterial({ color: 0xd7e8f0, roughness: .3, metalness: .2, transparent: true, opacity: .65 }));
    canopy.position.set(s.x, Y + 4.4, s.z); guide.add(canopy);
    for (let p = -1; p <= 1; p += 2) {
      const post = new THREE.Mesh(new THREE.BoxGeometry(.28, 5.3, .28), guideMat2);
      post.position.set(s.x + p * 12, Y + 2.1, s.z); guide.add(post);
    }
    const canopy2 = new THREE.Mesh(new THREE.BoxGeometry(28, .2, 7), new THREE.MeshStandardMaterial({ color: 0x506070, roughness: .5 }));
    canopy2.position.set(s.x, Y + 4.6, s.z); guide.add(canopy2);
    const signMat = new THREE.MeshBasicMaterial({ map: signTexture('MONORAIL', '#071d2b', '#8ceaff', s.name), transparent: true });
    const sign = new THREE.Mesh(new THREE.PlaneGeometry(6, 3), signMat);
    sign.position.set(s.x, Y + 2.8, s.z); sign.rotation.y = s.ang + Math.PI; guide.add(sign);
    // elevator tower to ground
    const towerX = s.x, towerZ = s.z + 10;
    const tower = new THREE.Mesh(new THREE.BoxGeometry(5.5, Y, 5.5), new THREE.MeshStandardMaterial({ color: 0x3f4c58, roughness: .35, metalness: .4 }));
    tower.position.set(towerX, Y / 2, towerZ); guide.add(tower);
    const glass = new THREE.Mesh(new THREE.BoxGeometry(4.2, Y - 1.5, 4.4), new THREE.MeshStandardMaterial({ color: 0x6fc5dd, transparent: true, opacity: .45, roughness: .1, metalness: .6 }));
    glass.position.set(towerX, Y / 2, towerZ); guide.add(glass);
    const eg = new THREE.Mesh(new THREE.BoxGeometry(6.4, .4, 6.4), guideMat);
    eg.position.set(towerX, Y + .4, towerZ); guide.add(eg);
    // entrance sign at ground
    const ent = new THREE.Group(); ent.position.set(towerX, 0, towerZ + 5);
    const post = new THREE.Mesh(new THREE.CylinderGeometry(.08, .1, 2.8, 6), guideMat2); post.position.y = 1.4; ent.add(post);
    const entSign = new THREE.Mesh(new THREE.PlaneGeometry(2.2, 1.1), new THREE.MeshBasicMaterial({ map: signTexture('NOVA RAIL', '#081c2b', '#8ceaff', s.name), transparent: true }));
    entSign.position.set(0, 3.2, 0); ent.add(entSign); guide.add(ent);
    city.addPOI('monorail', s.name + ' Monorail', towerX, towerZ + 2, 7, { icon: 'transit', station: i });
    s.tower = new THREE.Vector3(towerX, 0, towerZ);
    s.platformY = Y;
  }
  // monorail train geometry
  const train = buildMonorailTrain();
  train.position.set(0, Y + 1.1, -R);
  guide.add(train);
  root.add(guide);

  const loopLen = 4 * (2 * R);
  const monorail = {
    group: train, progress: 0, speed: 11, targetSpeed: 11, dwell: 0, manual: false,
    stations, Y, R, perimeter: loopLen, doorOpen: false, currentStation: -1, lastStation: -1,
    stopAt: null, riding: false,
    update(dt, elapsed) {
      if (this.manual) {
        this.targetSpeed = clamp(this.targetSpeed, 0, 24);
        this.speed = THREE.MathUtils.damp(this.speed, this.targetSpeed, 1.6, dt);
        this.speed *= (1 - dt * .12);
        this.progress = (this.progress + this.speed * dt) % this.perimeter;
        if (this.speed < 0) this.speed = 0;
        this.positionCars();
        return;
      }
      // automatic: stop at next station
      const next = this.nextStationDistance();
      if (this.dwell > 0) {
        this.dwell -= dt; this.speed = THREE.MathUtils.damp(this.speed, 0, 6, dt); this.doorOpen = true;
      } else {
        this.doorOpen = false;
        if (next < 26 && this.speed > 0) {
          this.speed = THREE.MathUtils.damp(this.speed, 0, 3.4, dt);
          if (next < 1.6) { this.dwell = 5.5; this.speed = 0; this.currentStation = this.stationAt(this.progress); }
        } else {
          this.speed = THREE.MathUtils.damp(this.speed, 11, 1.1, dt);
        }
        this.progress = (this.progress + this.speed * dt) % this.perimeter;
      }
      this.positionCars();
      this.animateDoors();
    },
    nextStationDistance() {
      let best = 1e9;
      for (const s of this.stations) {
        const p = this.stationProgress(s);
        let d = (p - this.progress + this.perimeter) % this.perimeter;
        if (d < 2) d = this.perimeter;
        best = Math.min(best, d);
      }
      return best;
    },
    stationProgress(s) { return ((s.z + R) / (4 * R)) * this.perimeter; },
    stationAt(p) {
      let best = -1, bd = 30;
      for (let i = 0; i < this.stations.length; i++) {
        const sp = this.stationProgress(this.stations[i]);
        let d = Math.abs(((p - sp + this.perimeter / 2) % this.perimeter) - this.perimeter / 2);
        if (d < bd) { bd = d; best = i; }
      }
      return best;
    },
    positionCars() {
      const pts = loopPoints(this.progress, this.perimeter, this.R);
      this.group.position.set(pts.x, this.Y + 1.1, pts.z);
      this.group.rotation.y = -pts.angle + Math.PI / 2;
      let rear = (this.progress - 15 + this.perimeter) % this.perimeter;
      for (let i = 1; i < this.group.userData.cars.length; i++) {
        const p = loopPoints(rear, this.perimeter, this.R);
        this.group.userData.cars[i].position.set(0, 0, -i * 5.4);
      }
    },
    animateDoors() {
      const doors = this.group.userData.doors || [];
      for (const d of doors) {
        d.scale.x = THREE.MathUtils.damp(d.scale.x, this.doorOpen ? .05 : 1, 5, dt);
      }
    },
    board() { this.dwell = 5; return true; },
    stationPositions() { return this.stations.map(s => s.tower); },
  };
  city.monorail = monorail;

  // --- ground railway (freight/commuter) ---
  const railY = .1, railZ = -446;
  const railGroup = new THREE.Group();
  const ballast = new THREE.Mesh(new THREE.BoxGeometry(1200, .25, 8), new THREE.MeshStandardMaterial({ color: 0x3d3a34, roughness: 1 }));
  ballast.position.set(0, .06, railZ); root.add(ballast);
  const sleeperGeo = new THREE.BoxGeometry(.3, .12, 3.4);
  const sleepers = new THREE.InstancedMesh(sleeperGeo, city.woodMat, 300);
  const tmp = new THREE.Object3D();
  for (let i = 0; i < 300; i++) {
    tmp.position.set(-600 + i * 4, railY + .1, railZ); tmp.rotation.set(0, Math.PI / 2, 0); tmp.updateMatrix(); sleepers.setMatrixAt(i, tmp.matrix);
  }
  root.add(sleepers);
  for (const side of [-1, 1]) {
    const rail = new THREE.Mesh(new THREE.BoxGeometry(1200, .12, .16), new THREE.MeshStandardMaterial({ color: 0x9aa0a4, roughness: .3, metalness: .8 }));
    rail.position.set(0, railY + .2, railZ + side * .75); root.add(rail);
  }
  // station
  const st = new THREE.Group();
  const platform = new THREE.Mesh(new THREE.BoxGeometry(90, 1.1, 8), city.concreteMat);
  platform.position.set(170, .55, -438); st.add(platform);
  const roof = new THREE.Mesh(new THREE.BoxGeometry(80, .3, 9), new THREE.MeshStandardMaterial({ color: 0x39424a, roughness: .6, metalness: .3 }));
  roof.position.set(170, 5.3, -438); st.add(roof);
  for (let x = -38; x <= 38; x += 12) {
    const post = new THREE.Mesh(new THREE.BoxGeometry(.2, 4.8, .2), city.metalMat);
    post.position.set(170 + x, 2.7, -438); st.add(post);
  }
  const stationSign = new THREE.Mesh(new THREE.PlaneGeometry(12, 3), new THREE.MeshBasicMaterial({ map: signTexture('NOVA CENTRAL', '#0b1b2b', '#cfefff', 'RAIL TERMINAL'), transparent: true }));
  stationSign.position.set(170, 3.7, -434); st.add(stationSign);
  const stairs = new THREE.Mesh(new THREE.BoxGeometry(9, 1.2, 6), city.concreteMat);
  stairs.position.set(170, .45, -430); st.add(stairs);
  root.add(st);
  city.addPOI('train', 'Nova Central Rail', 170, -430, 16, { icon: 'transit' });

  // commuter train
  const commuter = buildCommuterTrain();
  commuter.position.set(-420, railY + .3, railZ);
  root.add(commuter);
  city.rail = {
    group: commuter, speed: 16, progress: 0, length: 1200, dwell: 0,
    update(dt) {
      this.progress = (this.progress + this.speed * dt) % 1200;
      this.group.position.x = -600 + this.progress;
      if (this.speed > 0) this.group.userData.wheels?.forEach(w => w.rotation.x += dt * 8);
    },
  };

  // elevated highway (north edge), visual traffic
  const hwY = 8.5, hwZ = -392;
  const hw = new THREE.Group();
  const deck = new THREE.Mesh(new THREE.BoxGeometry(1280, .8, 20), new THREE.MeshStandardMaterial({ color: 0x353b42, roughness: .9 }));
  deck.position.set(0, hwY, hwZ); hw.add(deck);
  for (const side of [-1, 1]) {
    const rail = new THREE.Mesh(new THREE.BoxGeometry(1280, .9, .25), new THREE.MeshStandardMaterial({ color: 0x8d969e, roughness: .5, metalness: .5 }));
    rail.position.set(0, hwY + 1, hwZ + side * 9.8); hw.add(rail);
  }
  const pillarGeo2 = new THREE.CylinderGeometry(1.1, 1.3, hwY, 8);
  for (let x = -620; x <= 620; x += 40) {
    const p = new THREE.Mesh(pillarGeo2, city.concreteMat); p.position.set(x, hwY / 2, hwZ); hw.add(p);
  }
  root.add(hw);
  for (let i = 0; i < 12; i++) {
    const c = new THREE.Group();
    const body = new THREE.Mesh(new THREE.BoxGeometry(3.6, 1.1, 1.8), new THREE.MeshStandardMaterial({ color: pick([0x8b2f33, 0x2f4f7a, 0xd0d0c8, 0x2e2e34, 0x9a7b32]), roughness: .6, metalness: .3 }));
    body.position.y = .8; c.add(body);
    const cab = new THREE.Mesh(new THREE.BoxGeometry(1.9, .8, 1.6), new THREE.MeshStandardMaterial({ color: 0x1b2834, roughness: .2, metalness: .5 })); cab.position.set(-.1, 1.55, 0); c.add(cab);
    c.position.set(rand(-600, 600), hwY + .6, hwZ + (i % 2 ? 4 : -4));
    c.userData.speed = 16 + Math.random() * 10;
    c.userData.lane = hwZ;
    root.add(c); city.highwayCars.push(c);
  }

  // tunnel portal on east outskirt
  const portal = new THREE.Group();
  const arch = new THREE.Mesh(new THREE.BoxGeometry(6, 14, 30), new THREE.MeshStandardMaterial({ color: 0x5b5e62, roughness: .95 }));
  arch.position.set(430, 7, 120); portal.add(arch);
  const hole = new THREE.Mesh(new THREE.BoxGeometry(.2, 8, 14), new THREE.MeshBasicMaterial({ color: 0x05070a }));
  hole.position.set(427, 4.2, 120); portal.add(hole);
  root.add(portal);

  // Buses at terminal
  const busDepot = new THREE.Mesh(new THREE.PlaneGeometry(60, 30), new THREE.MeshStandardMaterial({ color: 0x2e3236, roughness: 1 }));
  busDepot.rotation.x = -Math.PI / 2; busDepot.position.set(96, .17, 336); root.add(busDepot);
