  runway.rotation.x = -Math.PI / 2; runway.position.set(cx + 60, .08, cz); root.add(runway);
  const lineMat = new THREE.MeshBasicMaterial({ color: 0xe8e6d9 });
  for (let i = -160; i < 160; i += 20) {
