  addMesh(group, box(wid * .98, bodyH, len * .98), bodyMat, 0, y0, 0);
  addMesh(group, box(wid * 1.0, .3, len * .99), trimMat, 0, cfg.wheelR + .25, 0);
  addMesh(group, box(wid * .96, .18, len * .99), silverMat, 0, y0 + bodyH * .2, 0);
