function buildBoat(color) {
  const cfg = VEHICLE_TYPES.boat;
  const group = new THREE.Group();
  const bodyMat = new THREE.MeshStandardMaterial({ color, roughness: .3, metalness: .3 });
  const hullShape = new THREE.Shape();
  hullShape.moveTo(-1.1, -3.1); hullShape.lineTo(1.1, -3.1); hullShape.lineTo(1.1, 1.4);
  hullShape.quadraticCurveTo(1.0, 2.7, 0, 3.1); hullShape.quadraticCurveTo(-1.0, 2.7, -1.1, 1.4); hullShape.lineTo(-1.1, -3.1);
  const hullGeo = new THREE.ExtrudeGeometry(hullShape, { depth: .8, bevelEnabled: true, bevelSize: .12, bevelThickness: .12, bevelSegments: 2 });
  hullGeo.rotateX(Math.PI / 2);
  const hull = new THREE.Mesh(hullGeo, bodyMat);
  hull.position.y = .9; hull.castShadow = true; group.add(hull);
  const deck = addMesh(group, box(1.8, .08, 4.8), new THREE.MeshStandardMaterial({ color: 0x9a8c74, roughness: .9 }), 0, 1.05, -.3);
  const stripe = addMesh(group, box(2.2, .12, 5.8), new THREE.MeshStandardMaterial({ color: 0x1a6a8a, roughness: .4 }), 0, .72, 0);
  // windshield
  addMesh(group, box(1.5, .5, .06), glassMat, 0, 1.45, .7, -.25, 0, 0);
  addMesh(group, box(1.4, .4, .06), glassMat, 0, 1.4, -.9, .2, 0, 0);
  // seats
  for (let i = 0; i < 2; i++) addMesh(group, box(.55, .18, .5), seatMat, -0.45 + i * .9, 1.28, -1.2);
  // console
  addMesh(group, box(1.0, .3, .5), trimMat, 0, 1.35, .6);
  addMesh(group, box(.4, .1, .35), new THREE.MeshBasicMaterial({ color: 0x67d8ff, toneMapped: false }), 0, 1.52, .6);
  // motor
  addMesh(group, box(.4, .65, .7), trimMat, 0, .8, -3.25);
  addLight(group, 0xcfeaff, 0, 1.0, 3.02, .3, .12, .08);
  addLight(group, 0x5a0b0b, 0, 1.0, -3.02, .3, .12, .08, { kind: 'brake' });
  // rails
  for (const s of [-1, 1]) addMesh(group, box(.04, .25, 3.2), silverMat, s * 1.05, 1.28, -.6);
  return { group, wheels: [], bodyMat, headMats: [], brakeMats: [], cfg, type: 'boat' };
}

function buildHelicopter(color) {
  const cfg = VEHICLE_TYPES.helicopter;
  const group = new THREE.Group();
  const bodyMat = new THREE.MeshStandardMaterial({ color, roughness: .3, metalness: .45 });
  const fusGeo = new THREE.SphereGeometry(1.05, 18, 14);
  const fus = new THREE.Mesh(fusGeo, bodyMat);
  fus.scale.set(1.0, 1.0, 1.9); fus.position.y = 1.65;
  fus.castShadow = true; group.add(fus);
  const cockpit = new THREE.Mesh(new THREE.SphereGeometry(.92, 16, 12), glassMat);
  cockpit.scale.set(.98, .8, 1.0); cockpit.position.set(0, 1.75, 1.0); group.add(cockpit);
  const tail = addMesh(group, box(.28, .28, 2.9), bodyMat, 0, 1.75, -2.1);
  const fin = addMesh(group, box(.1, .8, .6), bodyMat, 0, 2.2, -3.4);
  const skidMat = new THREE.MeshStandardMaterial({ color: 0x3a4045, roughness: .6, metalness: .5 });
  for (const s of [-1, 1]) {
    addMesh(group, box(.1, .1, 3.0), skidMat, s * .85, .28, 0);
    addMesh(group, box(.1, .7, .1), skidMat, s * .7, .62, .7, 0, 0, -.25);
    addMesh(group, box(.1, .7, .1), skidMat, s * .7, .62, -.7, 0, 0, .25);
  }
  // rotor
  const rotor = new THREE.Group(); rotor.position.set(0, 2.6, 0);
  addMesh(rotor, box(.18, .12, 5.4), trimMat, 0, 0, 0, 0, 0, 0);
  addMesh(rotor, box(5.4, .06, .18), trimMat, 0, 0, 0);
  const hub = new THREE.Mesh(new THREE.CylinderGeometry(.14, .14, .4, 8), rimMat); hub.position.y = .1; rotor.add(hub);
  group.add(rotor);
  const tailRotor = new THREE.Group(); tailRotor.position.set(.25, 2.1, -3.45);
  addMesh(tailRotor, box(.06, 1.4, .16), trimMat, 0, 0, 0);
  addMesh(tailRotor, box(.06, .16, 1.4), trimMat, 0, 0, 0);
  group.add(tailRotor);
  // lights
  addLight(group, 0xf2f6e9, -.65, 1.3, 1.65, .18, .18, .08);
  addLight(group, 0xf2f6e9, .65, 1.3, 1.65, .18, .18, .08);
  const red = addLight(group, 0xff2020, 0, 2.2, -2.8, .12, .12, .12);
  const green = addLight(group, 0x20ff40, -1.05, 1.5, -.8, .1, .1, .1);
  // interior seats
  addMesh(group, box(.5, .3, .5), seatMat, -.35, 1.5, .2);
  addMesh(group, box(.5, .3, .5), seatMat, .35, 1.5, .2);
  return { group, wheels: [], bodyMat, headMats: [], brakeMats: [], rotor, tailRotor, cfg, type: 'helicopter' };
}

export function buildVehicleModel(type, color, opts = {}) {
  let v;
  if (['bus'].includes(type)) v = buildBus(color);
  else if (['truck', 'construction', 'fire', 'ambulance'].includes(type)) v = buildTruck(type, color);
  else if (type === 'motorcycle') v = buildMotorcycle(color);
  else if (type === 'boat') v = buildBoat(color);
  else if (type === 'helicopter') v = buildHelicopter(color);
  else v = buildCarLike(type, color);
  v.group.userData.vehicleType = type;
  v.group.userData.wheels = v.wheels;
  if (v.rider) v.group.userData.rider = v.rider;
  v.color = color;
  if (opts.traffic && v.rider) v.rider.visible = true;
  return v;
}

export function randomVehicleColor(type) {
  if (type === 'taxi') return 0xe8b52a;
  if (type === 'police') return 0xe8edf0;
  if (type === 'fire') return 0xb8242e;
  if (type === 'ambulance') return 0xe8ecee;
  if (type === 'construction') return 0xd6a51f;
  return pick(COLORS);
}

export function setLightState(headMats, brakeMats, turnMats, opts) {
  const { lightsOn = false, braking = false, left = false, right = false, hazard = false } = opts;
  for (const m of headMats) m.color.setHex(lightsOn ? 0xfff6d8 : 0x4b4d46);
  for (const m of brakeMats) m.color.setHex(braking ? 0xff2b2b : lightsOn ? 0x7a1010 : 0x3a0808);
  if (turnMats.length >= 2) {
    const l = left || hazard;
    const r = right || hazard;
    turnMats[0].color.setHex(l ? 0xffb020 : 0x3a2a08);
    turnMats[1].color.setHex(r ? 0xffb020 : 0x3a2a08);
  }
}

import * as THREE from 'three';
import { rand, pick, TAU } from './utils.js';

class ParticlePool {
  constructor(scene, capacity, additive) {
    this.capacity = capacity;
    this.parts = [];
    const geo = new THREE.BufferGeometry();
    this.pos = new Float32Array(capacity * 3);
    this.col = new Float32Array(capacity * 3);
    this.alpha = new Float32Array(capacity);
    this.size = new Float32Array(capacity);
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    const mat = new THREE.ShaderMaterial({
      transparent: true, depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
      uniforms: {},
      vertexShader: `
        attribute vec3 aColor; attribute float aAlpha; attribute float aSize;
        varying vec3 vColor; varying float vAlpha;
        void main(){
          vColor = aColor; vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position,1.0);
          gl_PointSize = aSize * (260.0 / max(1.0, -mv.z));
          gl_Position = projectionMatrix * mv;
        }`,
      fragmentShader: `
        varying vec3 vColor; varying float vAlpha;
        void main(){
          vec2 c = gl_PointCoord - .5;
          float d = length(c);
          float a = smoothstep(.5, .08, d) * vAlpha;
          if(a < .01) discard;
          gl_FragColor = vec4(vColor, a);
        }`,
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    scene.add(this.points);
    for (let i = 0; i < capacity; i++) this.parts.push({ alive: false, life: 0, maxLife: 1, x: 0, y: -999, z: 0, vx: 0, vy: 0, vz: 0, size: 1, grow: 0, color: new THREE.Color(), gravity: 0, drag: 0.98 });
  }
  spawn(x, y, z, opts = {}) {
    let p = this.parts.find(q => !q.alive);
    if (!p) p = this.parts[(Math.random() * this.capacity) | 0];
    p.alive = true;
    p.x = x; p.y = y; p.z = z;
    p.vx = opts.vx ?? rand(-.6, .6); p.vy = opts.vy ?? rand(.6, 2.2); p.vz = opts.vz ?? rand(-.6, .6);
    p.life = p.maxLife = opts.life ?? rand(.8, 2.2);
    p.size = opts.size ?? rand(1, 3);
    p.grow = opts.grow ?? 1.2;
    p.gravity = opts.gravity ?? 0;
    p.drag = opts.drag ?? .97;
    p.color.set(opts.color ?? 0xb8b8b8);
    return p;
  }
  update(dt) {
    for (let i = 0; i < this.capacity; i++) {
      const p = this.parts[i];
      if (!p.alive) { this.alpha[i] = 0; this.pos[i * 3 + 1] = -999; continue; }
      p.life -= dt;
      if (p.life <= 0) { p.alive = false; this.alpha[i] = 0; this.pos[i * 3 + 1] = -999; continue; }
      p.vy -= p.gravity * dt;
      p.vx *= Math.pow(p.drag, dt * 60); p.vz *= Math.pow(p.drag, dt * 60); p.vy *= Math.pow(p.drag, dt * 60);
      p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt;
      p.size += p.grow * dt;
      this.pos[i * 3] = p.x; this.pos[i * 3 + 1] = p.y; this.pos[i * 3 + 2] = p.z;
      this.col[i * 3] = p.color.r; this.col[i * 3 + 1] = p.color.g; this.col[i * 3 + 2] = p.color.b;
      this.alpha[i] = (p.life / p.maxLife) * (optsAlpha(p));
      this.size[i] = p.size;
    }
    const g = this.points.geometry;
    g.attributes.position.needsUpdate = true;
    g.attributes.aColor.needsUpdate = true;
    g.attributes.aAlpha.needsUpdate = true;
    g.attributes.aSize.needsUpdate = true;
  }
}
function optsAlpha(p) { return Math.min(1, p.maxLife > .5 ? .82 : .95); }

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.smoke = new ParticlePool(scene, 420, false);
    this.sparks = new ParticlePool(scene, 260, true);
    this.fire = new ParticlePool(scene, 320, true);
    this.rain = null;
    this.lightningTimer = 8;
    this.flash = 0;
    this.sirens = [];
    this.wakes = new ParticlePool(scene, 200, false);
    this.wakes.points.material.blending = THREE.NormalBlending;
  }

  spawnSmoke(x, y, z, amount = 1, color = 0x8f9298, size = 2) {
    for (let i = 0; i < amount; i++) this.smoke.spawn(x + rand(-.4, .4), y, z + rand(-.4, .4), { color, size: size + rand(0, 1.4), grow: 1.6, life: rand(1.4, 3.4), vy: rand(.6, 2), drag: .96 });
  }
  smokeAtVehicle(v, dt) {
    if (v.smokeAcc === undefined) v.smokeAcc = 0;
    v.smokeAcc += dt;
    if (v.health < 55 && v.smokeAcc > .1) {
      v.smokeAcc = 0;
      const p = v.group.position;
      this.spawnSmoke(p.x, p.y + v.cfg.height * .7, p.z, 1, v.health < 25 ? 0x2b2b2b : 0x9a9a9a, v.health < 25 ? 3 : 1.8);
      if (v.health < 20 && Math.random() < .3) this.sparks.spawn(p.x, p.y + .8, p.z, { color: 0xff7b2a, size: 1.2, life: .5, vy: rand(.4, 1.6), vx: rand(-1, 1), vz: rand(-1, 1), gravity: 2 });
    }
  }
  sparksAt(x, y, z, n = 12, color = 0xffb347) {
    for (let i = 0; i < n; i++) {
      this.sparks.spawn(x, y, z, {
        color, size: rand(.5, 1.4), life: rand(.25, .9), grow: -.2,
        vx: rand(-4, 4), vy: rand(1, 5), vz: rand(-4, 4), gravity: 9, drag: .98,
      });
    }
  }
  fireAt(x, y, z, scale = 1) {
    this.fire.spawn(x + rand(-1, 1) * scale, y + rand(0, 1.5) * scale, z + rand(-1, 1) * scale, {
      color: pick([0xff7b24, 0xffb347, 0xff4a1e, 0xffd36a]), size: rand(2, 4) * scale, grow: 2.2,
      life: rand(.4, 1.1), vy: rand(1.6, 4.2), vx: rand(-.6, .6), vz: rand(-.6, .6), drag: .94,
    });
    if (Math.random() < .25) this.spawnSmoke(x, y + 3, z, 1, 0x2e2e2e, 4 * scale);
  }
  debris(x, y, z, n = 10) {
    for (let i = 0; i < n; i++) {
      this.sparks.spawn(x, y, z, {
        color: pick([0x555b5f, 0x8f9195, 0x3d4246, 0x9b7c52]), size: rand(.8, 2.2), life: rand(.8, 2),
        vx: rand(-5, 5), vy: rand(2, 7), vz: rand(-5, 5), gravity: 12, drag: .99,
      });
    }
  }
  explosion(x, y, z) {
    this.sparksAt(x, y, z, 60, 0xffa53b);
    this.sparksAt(x, y, z, 30, 0xffe28a);
    for (let i = 0; i < 20; i++) this.spawnSmoke(x + rand(-2, 2), y + 1, z + rand(-2, 2), 1, 0x2a2a2a, 5);
    for (let i = 0; i < 24; i++) this.fireAt(x, y, z, 2);
    this.debris(x, y + 1, z, 20);
  }
  setWeather(kind) {
    if (this.rain) { this.scene.remove(this.rain); this.rain.geometry.dispose(); this.rain = null; }
    if (kind === 'rain' || kind === 'storm') {
      const n = 1600;
      const geo = new THREE.BufferGeometry();
      const pos = new Float32Array(n * 6);
      for (let i = 0; i < n; i++) {
        const x = rand(-80, 80), y = rand(0, 65), z = rand(-80, 80);
        pos[i * 6] = x; pos[i * 6 + 1] = y; pos[i * 6 + 2] = z;
        pos[i * 6 + 3] = x + .4; pos[i * 6 + 4] = y + 2.4; pos[i * 6 + 5] = z;
      }
      geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
      const mat = new THREE.LineBasicMaterial({ color: 0xb8d4ee, transparent: true, opacity: kind === 'storm' ? .42 : .28 });
      this.rain = new THREE.LineSegments(geo, mat);
      this.rain.frustumCulled = false;
      this.scene.add(this.rain);
    } else if (kind === 'snow') {
      const n = 1800;
      const geo = new THREE.BufferGeometry();
      const pos = new Float32Array(n * 3);
      for (let i = 0; i < n; i++) { pos[i * 3] = rand(-70, 70); pos[i * 3 + 1] = rand(0, 55); pos[i * 3 + 2] = rand(-70, 70); }
      geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
      const mat = new THREE.PointsMaterial({ color: 0xffffff, size: .55, transparent: true, opacity: .8, depthWrite: false });
      this.rain = new THREE.Points(geo, mat);
      this.rain.frustumCulled = false;
      this.scene.add(this.rain);
    }
    this.weatherKind = kind;
  }
  update(dt, elapsed, playerPos, weather) {
    this.smoke.update(dt); this.sparks.update(dt); this.fire.update(dt); this.wakes.update(dt);
    if (this.rain && playerPos) {
      const pos = this.rain.geometry.attributes.position;
      const arr = pos.array;
      const isLines = this.weatherKind === 'rain' || this.weatherKind === 'storm';
      const speed = this.weatherKind === 'storm' ? 58 : 38;
      const step = isLines ? 6 : 3;
      for (let i = 0; i < arr.length; i += step) {
        arr[i + 1] -= speed * dt;
        if (arr[i + 1] < -2) {
          arr[i] = playerPos.x + rand(-65, 65); arr[i + 2] = playerPos.z + rand(-65, 65); arr[i + 1] = 55;
          if (isLines) { arr[i + 3] = arr[i] + .4; arr[i + 4] = arr[i + 1] + 2.4; arr[i + 5] = arr[i + 2]; }
        }
        if (isLines) { arr[i + 3] = arr[i] + .4; arr[i + 4] = arr[i + 1] + 2.4; arr[i + 5] = arr[i + 2]; }
      }
      this.rain.position.set(playerPos.x, 0, playerPos.z);
      pos.needsUpdate = true;
    }
    if (weather === 'storm') {
      this.lightningTimer -= dt;
      if (this.lightningTimer <= 0) {
        this.lightningTimer = rand(6, 18);
        this.flash = 1;
      }
      if (this.flash > 0) {
        this.flash -= dt * 3.5;
      }
    }
  }
}

import * as THREE from 'three';
import { clamp, lerp, rand, pick, chance, TAU, normAngle, formatMoney } from './utils.js';
import { VEHICLE_TYPES, buildVehicleModel, randomVehicleColor, setLightState } from './models.js';
import { HALF_ROAD, NODE_POS } from './city.js';

const AXES = [[1, 0], [-1, 0], [0, 1], [0, -1]];

export class Vehicle {
  constructor(game, type, x, z, heading = 0, opts = {}) {
    this.game = game;
    this.type = type;
    this.cfg = VEHICLE_TYPES[type];
    this.model = buildVehicleModel(type, opts.color ?? this.cfg.color ?? randomVehicleColor(type), { traffic: opts.traffic });
    this.group = this.model.group;
    this.wheels = this.model.wheels || [];
    this.headMats = this.model.headMats || [];
    this.brakeMats = this.model.brakeMats || [];
    this.turnMats = this.model.turnMats || [];
    this.bodyMat = this.model.bodyMat;
    this.rotor = this.model.rotor;
    this.tailRotor = this.model.tailRotor;
    this.rider = this.model.rider;
    this.group.position.set(x, opts.y ?? 0.02, z);
    this.group.rotation.y = heading;
    game.scene.add(this.group);
    this.pos = this.group.position;
    this.heading = heading;
    this.velocity = new THREE.Vector2();
    this.speed = 0;
    this.steer = 0;
    this.throttle = 0;
    this.brakeInput = 0;
    this.handbrake = false;
    this.health = 100;
    this.fuel = this.cfg.fuel;
    this.engineOn = true;
    this.lightsOn = false;
    this.indicator = 0;
    this.damageFlash = 0;
    this.lastCrash = 0;
    this.wheelSpin = 0;
    this.mode = opts.mode || (opts.traffic ? 'traffic' : 'parked');
    this.service = opts.service || null;
    this.owned = !!opts.owned;
    this.knock = new THREE.Vector2();
    this.knockTimer = 0;
    this.smokeAcc = 0;
    this.driverVisible = false;
    this.verticalVelocity = 0;
    this.altitude = opts.y ?? 0;
    this.rotorAngle = 0;
    this.traffic = null;
    this.parkedName = opts.name || null;
    this.interiorLight = 0;
    this.isPlayer = false;
    this.enterable = true;
    this.doorOpen = false;
    this.turret = null;
    this.wakeAcc = 0;
    this.speedKmh = 0;
    this.brakeOn = false;
    this.cruise = 0;
    this.lodTick = Math.random() * 4;
    if (opts.traffic) this.initTraffic();
    if (this.service) this.addServiceLights();
  }

  get isBoat() { return !!this.cfg.isBoat; }
  get isAir() { return !!this.cfg.isAir; }
  get halfLen() { return this.cfg.len / 2; }
  get halfWid() { return this.cfg.wid / 2; }

  addServiceLights() {
    const g = new THREE.Group();
    const redM = new THREE.MeshBasicMaterial({ color: 0xff2020, toneMapped: false });
    const blueM = new THREE.MeshBasicMaterial({ color: 0x2a5bff, toneMapped: false });
    const y = this.type === 'motorcycle' ? 1.2 : this.cfg.height + (this.type === 'bus' ? .1 : .02);
    const geo = new THREE.BoxGeometry(this.type === 'fire' ? 1.4 : .55, .16, .38);
    const r = new THREE.Mesh(geo, redM); r.position.set(-.3, y, this.type === 'sedan' ? 0 : 0);
    const b = new THREE.Mesh(geo, blueM); b.position.set(.3, y, 0);
    g.add(r, b);
    const l = new THREE.PointLight(0xff3333, 0, 18, 2); l.position.set(0, y, 0);
    g.add(l);
    this.group.add(g);
    this.serviceLights = { redM, blueM, light: l, group: g };
  }

  initTraffic() {
    let node = this.game.city.nearestNode(this.pos.x, this.pos.z);
    let dir = pick(AXES);
    let next = this.getNeighbor(node, dir);
    let guard = 0;
    while (!next && guard++ < 8) { dir = pick(AXES); next = this.getNeighbor(node, dir); }
    if (!next) { this.mode = 'parked'; return; }
    this.traffic = {
      node, next, dir, t: rand(2, 60), lane: 3.9, cruise: this.type === 'bus' || this.type === 'truck' ? rand(8, 10) : rand(10, 14),
      turnTimer: 0, stopTimer: 0,
    };
    const p = this.lanePoint(this.traffic);
    this.pos.x = p.x; this.pos.z = p.z;
    this.heading = Math.atan2(dir[0], dir[1]);
    this.group.rotation.y = this.heading;
    this.mode = 'traffic';
  }

  getNeighbor(node, dir) {
    const i = node.i + dir[0], j = node.j + dir[1];
    if (i < 0 || i >= 9 || j < 0 || j >= 9) return null;
    return this.game.city.nodeGrid[i][j];
  }

  lanePoint(tr, ahead = 0) {
    const nx = tr.node.x + tr.dir[0] * (tr.t + ahead);
    const nz = tr.node.z + tr.dir[1] * (tr.t + ahead);
    const rx = -tr.dir[1], rz = tr.dir[0];
    return { x: nx + rx * tr.lane, z: nz + rz * tr.lane };
  }

  chooseNext(tr) {
    const options = [];
    const back = [-tr.dir[0], -tr.dir[1]];
    for (const d of AXES) {
      if (d[0] === back[0] && d[1] === back[1]) continue;
      if (this.getNeighbor(tr.next, d)) options.push(d);
    }
    if (!options.length) return [-tr.dir[0], -tr.dir[1]];
    // prefer straight
    const straight = options.filter(d => d[0] === tr.dir[0] && d[1] === tr.dir[1]);
    if (straight.length && Math.random() < .55) return straight[0];
    return pick(options);
  }

  updateTraffic(dt, elapsed, night, weather) {
    const tr = this.traffic;
    if (!tr) return;
    if (this.knockTimer > 0) {
      this.knockTimer -= dt;
      this.pos.x += this.knock.x * dt;
      this.pos.z += this.knock.y * dt;
      this.knock.multiplyScalar(1 - dt * 4);
    }
    const segLen = 96;
    // signal ahead
    const axis = tr.dir[0] !== 0 ? 'x' : 'z';
    const distToNode = segLen - tr.t;
    let targetSpeed = tr.cruise;
    let stop = false;
    if (distToNode < 25) {
      const state = this.game.city.signalState(tr.next, axis, elapsed);
      if (state === 'red' || (state === 'yellow' && distToNode > 8)) {
        if (distToNode < 19) stop = true;
      }
    }
    // forward obstacle: traffic and player vehicles
    if (!stop) {
      const fx = Math.sin(this.heading), fz = Math.cos(this.heading);
      for (const other of this.game.vehicles.vehicles) {
        if (other === this) continue;
        const dx = other.pos.x - this.pos.x, dz = other.pos.z - this.pos.z;
        const d = Math.hypot(dx, dz);
        if (d < (other.cfg.len + this.cfg.len) * .5 + 4 && d > 0.01) {
          const dot = (dx * fx + dz * fz) / d;
          if (dot > .7) { stop = true; break; }
        }
      }
      // pedestrians in front
      const ped = this.game.npcs?.anyInFront(this.pos.x, this.pos.z, this.heading, 8);
      if (ped) stop = true;
    }
    if (stop) targetSpeed = 0;
    if (this.health < 15) targetSpeed = 0;
    const accel = stop ? this.cfg.brake * .8 : this.cfg.accel * .55;
    this.speed = this.speed < targetSpeed ? Math.min(targetSpeed, this.speed + accel * dt) : Math.max(targetSpeed, this.speed - this.cfg.brake * dt);
    this.brakeOn = stop && this.speed > .1;
    // steering
    const p = this.lanePoint(tr, 10);
    const dx = p.x - this.pos.x, dz = p.z - this.pos.z;
    const desired = Math.atan2(dx, dz);
    let diff = normAngle(desired - this.heading);
    const turnRate = clamp(this.speed * .35, 0, 2.2);
    this.heading = normAngle(this.heading + clamp(diff, -turnRate * dt, turnRate * dt));
    // move
    const fx = Math.sin(this.heading), fz = Math.cos(this.heading);
    this.pos.x += fx * this.speed * dt;
    this.pos.z += fz * this.speed * dt;
    this.group.rotation.y = this.heading;
    tr.t += this.speed * dt;
    // lane correction
    const lp = this.lanePoint(tr, 0);
    this.pos.x += (lp.x - this.pos.x) * Math.min(1, dt * 1.5);
    this.pos.z += (lp.z - this.pos.z) * Math.min(1, dt * 1.5);
    if (tr.t >= segLen) {
      tr.t -= segLen;
      tr.node = tr.next;
      tr.dir = this.chooseNext(tr);
      tr.next = this.getNeighbor(tr.node, tr.dir);
      if (!tr.next) { tr.node = this.game.city.nearestNode(this.pos.x, this.pos.z); tr.dir = pick(AXES); tr.next = this.getNeighbor(tr.node, tr.dir); }
    }
    // visuals
    this.animateWheels(dt);
    this.speedKmh = this.speed * 3.6;
    if (this.lightsOn !== (night > .4 || weather !== 'clear')) { this.lightsOn = night > .4 || weather !== 'clear'; }
    setLightState(this.headMats, this.brakeMats, this.turnMats, { lightsOn: this.lightsOn, braking: this.brakeOn || this.speed < .2 });
    if (this.serviceLights) {
      const on = Math.floor(elapsed * 5) % 2 === 0;
      this.serviceLights.redM.color.setHex(on ? 0xff2020 : 0x300808);
      this.serviceLights.blueM.color.setHex(on ? 0x0a0a30 : 0x2a5bff);
      this.serviceLights.light.color.setHex(on ? 0xff2020 : 0x2a5bff);
      this.serviceLights.light.intensity = on ? 2.6 : 2.2;
    }
  }

  updatePlayer(dt, controls, weather, elapsed, night) {
    this.isPlayer = true;
    if (this.isAir) return this.updateHelicopter(dt, controls, night);
    if (this.isBoat) return this.updateBoat(dt, controls, weather, night);
    const cfg = this.cfg;
    const f = new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading));
    const r = new THREE.Vector2(-f.y, f.x);
    let vf = this.velocity.dot(f);
    let vr = this.velocity.dot(r);
    const damageFactor = clamp(1 - (100 - this.health) / 150, .35, 1);
    const hasFuel = this.fuel > 0.1;
    const engine = this.engineOn && hasFuel && this.health > 6;
    this.throttle = controls.throttle || 0;
    this.brakeInput = controls.brake || 0;
    this.handbrake = !!controls.handbrake;
    const offroad = !this.game.city.isOnRoad(this.pos.x, this.pos.z);
    const wet = weather === 'rain' || weather === 'storm';
    const maxSpeed = cfg.maxSpeed * damageFactor * (offroad ? .62 : 1) * (wet ? .86 : 1);
    // reverse handling
    if (this.brakeInput > 0 && vf <= .4) {
      if (engine) vf -= cfg.accel * .45 * dt * damageFactor;
    } else if (this.brakeInput > 0) {
      vf -= cfg.brake * this.brakeInput * dt;
    }
    if (this.throttle > 0 && engine) {
      const power = cfg.accel * (1 - clamp(Math.abs(vf) / maxSpeed, 0, 1) * .72);
      vf += power * this.throttle * dt * damageFactor;
    }
    vf = clamp(vf, -maxSpeed * .35, maxSpeed);
    // drag + rolling
    vf *= 1 - dt * (offroad ? 1.2 : .22);
    vf -= Math.sign(vf) * Math.min(Math.abs(vf), (offroad ? 4.5 : 0.8) * dt);
    // lateral grip
    let grip = cfg.grip * (wet ? .52 : 1) * (offroad ? .55 : 1);
    if (this.handbrake) grip *= .16;
    if (this.health < 40) grip *= .86;
    vr *= Math.exp(-grip * dt);
    // steering
    const steerTarget = controls.steer || 0;
    this.steer = lerp(this.steer, steerTarget, clamp(dt * 8, 0, 1));
    const speedFactor = clamp(Math.abs(vf) / 7, 0, 1);
    const turnBoost = this.handbrake ? 1.45 : 1;
    const turnRate = 1.5 * speedFactor * (1 - clamp(Math.abs(vf) / cfg.maxSpeed, 0, 1) * .38) * turnBoost;
    this.heading = normAngle(this.heading + this.steer * turnRate * dt * (vf < 0 ? -1 : 1));
    // wet slide adds lateral velocity through the turn
    if (wet || this.handbrake) {
      vr += this.steer * vf * (wet ? .09 : .2) * dt * (this.handbrake ? 2.4 : 1);
    }
    const nf = new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading));
    const nr = new THREE.Vector2(-nf.y, nf.x);
    this.velocity.set(nf.x * vf + nr.x * vr, nf.y * vf + nr.y * vr);
    this.pos.x += this.velocity.x * dt;
    this.pos.z += this.velocity.y * dt;
    this.group.rotation.y = this.heading;
    // body roll / pitch
    if (this.wheels.length) {
      this.group.rotation.z = lerp(this.group.rotation.z, -this.steer * clamp(vf / 40, 0, 1) * .055, dt * 5);
      this.group.rotation.x = lerp(this.group.rotation.x, clamp((this.throttle - this.brakeInput) * .012, -.02, .02), dt * 4);
    }
    this.speed = vf;
    this.speedKmh = Math.abs(vf) * 3.6;
    this.brakeOn = this.brakeInput > 0 || (this.throttle === 0 && Math.abs(vf) > .2) || this.handbrake;
    // fuel
    if (engine) {
      this.fuel = Math.max(0, this.fuel - dt * (0.011 + Math.abs(vf) * .00075 * (this.throttle > 0 ? 2.2 : 1)));
    }
    // collisions
    this.resolveWorldCollisions(dt, vf);
    this.animateWheels(dt);
    this.animateLights(elapsed, night, controls);
    if (this.health < 55) this.game.effects.smokeAtVehicle(this, dt);
    if (hasFuel === false && engine) { this.engineOn = false; }
  }

  updateHelicopter(dt, controls, night) {
    const cfg = this.cfg;
    const hasFuel = this.fuel > 0.1;
    const engine = this.engineOn && hasFuel;
    this.throttle = controls.throttle || 0;
    this.brakeInput = controls.brake || 0;
    this.steer = controls.steer || 0;
    const up = controls.up || 0, down = controls.down || 0;
    const targetVY = engine ? (up - down) * 11 : -9;
    this.verticalVelocity = lerp(this.verticalVelocity, targetVY, dt * 2.2);
    this.altitude = Math.max(0.5, this.altitude + this.verticalVelocity * dt);
    const f = new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading));
    let forwardSpeed = this.velocity.dot(f);
    const targetSpeed = engine ? this.throttle * cfg.maxSpeed - this.brakeInput * 10 : 0;
    forwardSpeed = lerp(forwardSpeed, targetSpeed, dt * .7);
    this.heading = normAngle(this.heading + this.steer * dt * (1.15 + clamp(Math.abs(forwardSpeed) / 40, 0, .4)));
    const nf = new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading));
    this.velocity.set(nf.x * forwardSpeed, nf.y * forwardSpeed);
    this.pos.x += this.velocity.x * dt;
    this.pos.z += this.velocity.y * dt;
    this.pos.y = lerp(this.pos.y, this.altitude + Math.sin(performance.now() * .001) * .06, dt * 5);
    this.group.rotation.y = this.heading;
    this.group.rotation.z = lerp(this.group.rotation.z, -this.steer * .18 - this.velocity.x * .001, dt * 2);
    this.group.rotation.x = lerp(this.group.rotation.x, clamp(-forwardSpeed * .004, -.16, .16), dt * 2);
    this.speed = Math.abs(forwardSpeed);
    this.speedKmh = Math.abs(forwardSpeed) * 3.6;
    this.fuel = Math.max(0, this.fuel - dt * (0.03 + (up ? .04 : 0)));
    this.rotorAngle += dt * (engine ? 42 : 8);
    this.model.rotor.rotation.y = this.rotorAngle;
    if (this.model.tailRotor) this.model.tailRotor.rotation.x = this.rotorAngle * 1.4;
    if (this.rotor) this.rotor.rotation.y = this.rotorAngle;
    this.brakeOn = false;
    // building crash
    if (this.altitude < 30) {
      const hit = this.game.city.collideCircle(this.pos.x, this.pos.z, 3);
      if (hit && hit.box.height > this.pos.y) {
        this.pos.x -= hit.nx * hit.pen; this.pos.z -= hit.nz * hit.pen;
        this.health = Math.max(0, this.health - 12);
        this.game.effects.sparksAt(this.pos.x, this.pos.y, this.pos.z, 14);
        this.verticalVelocity = 2;
      }
    }
    if (this.pos.y < 2.2) {
      this.pos.y = 2.2; this.altitude = 2.2; this.verticalVelocity = 0;
      if (controls.up) { this.altitude = 2.4; }
    }
    if (this.health < 55) this.game.effects.smokeAtVehicle(this, dt);
    this.animateLights(performance.now() / 1000, night, controls);
    if (!engine && this.altitude > 1) { this.altitude = Math.max(.5, this.altitude - dt * 4); }
  }

  updateBoat(dt, controls, weather, night) {
    const cfg = this.cfg;
    const f = new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading));
    const r = new THREE.Vector2(-f.y, f.x);
    let vf = this.velocity.dot(f);
    let vr = this.velocity.dot(r);
    this.throttle = controls.throttle || 0;
    this.brakeInput = controls.brake || 0;
    this.steer = controls.steer || 0;
    const engine = this.engineOn && this.fuel > .1;
    if (engine && this.throttle > 0) vf += cfg.accel * this.throttle * dt * (1 - clamp(vf / cfg.maxSpeed, 0, 1) * .6);
    if (this.brakeInput > 0) vf -= cfg.brake * this.brakeInput * dt;
    vf *= 1 - dt * .25;
    vf = clamp(vf, -4, cfg.maxSpeed);
    vr *= Math.exp(-1.6 * dt);
    this.heading = normAngle(this.heading + this.steer * 1.1 * clamp(Math.abs(vf) / 8, 0, 1) * dt);
    const nf = new THREE.Vector2(Math.sin(this.heading), Math.cos(this.heading));
    this.velocity.set(nf.x * vf, nf.y * vf);
    this.pos.x += this.velocity.x * dt;
    this.pos.z += this.velocity.y * dt;
    // water bounds
    if (this.pos.z < 492) { this.pos.z = 492; this.velocity.y = Math.abs(this.velocity.y) * .2; vf *= .2; }
    if (this.pos.z > 1400) this.pos.z = 1400;
    this.pos.y = .25 + Math.sin(performance.now() * .0012 + this.pos.x * .01) * .12;
    this.group.rotation.y = this.heading;
    this.group.rotation.z = lerp(this.group.rotation.z, this.steer * .08, dt * 3);
    this.group.rotation.x = lerp(this.group.rotation.x, Math.sin(performance.now() * .0015) * .02, dt * 2);
    this.speed = vf;
    this.speedKmh = Math.abs(vf) * 3.6;
    this.fuel = Math.max(0, this.fuel - dt * (.02 + this.throttle * .04));
    this.animateLights(performance.now() / 1000, night, controls);
    if (Math.abs(vf) > 3) {
      this.wakeAcc += dt;
      if (this.wakeAcc > .08) {
        this.wakeAcc = 0;
        const back = new THREE.Vector2(-Math.sin(this.heading), -Math.cos(this.heading));
        this.game.effects.wakes.spawn(this.pos.x + back.x * 3.2, this.pos.y + .2, this.pos.z + back.y * 3.2, {
          color: 0xd7f1ff, size: 1.2, grow: 2.4, life: .9, vy: .2, vx: rand(-.4, .4), vz: rand(-.4, .4), drag: .9,
        });
      }
    }
    if (this.health < 55) this.game.effects.smokeAtVehicle(this, dt);
  }

  resolveWorldCollisions(dt, vf) {
    const len = this.cfg.len;
    const rad = this.cfg.wid * .46;
    const offsets = [-len * .32, 0, len * .32];
    const f = { x: Math.sin(this.heading), z: Math.cos(this.heading) };
    let hitAny = false, maxPen = 0, hitN = null;
    for (const o of offsets) {
      const cx = this.pos.x + f.x * o, cz = this.pos.z + f.z * o;
      const hit = this.game.city.collideCircle(cx, cz, rad);
      if (hit) {
        this.pos.x += hit.nx * hit.pen;
        this.pos.z += hit.nz * hit.pen;
        hitAny = true;
        if (hit.pen > maxPen) { maxPen = hit.pen; hitN = hit; }
      }
    }
    if (hitAny) {
      const impact = Math.abs(vf) + maxPen * 8;
      if (impact > 1.6) {
        const nx = hitN.nx, nz = hitN.nz;
        const vn = this.velocity.x * nx + this.velocity.y * nz;
        if (vn < 0) {
          this.velocity.x -= nx * vn * 1.35;
          this.velocity.y -= nz * vn * 1.35;
        }
        this.velocity.multiplyScalar(.72);
        const dmg = clamp((impact - 1.2) * .9, 0, 30);
        this.applyDamage(dmg, { x: this.pos.x + f.x * (len * .32), y: this.pos.y + .7, z: this.pos.z + f.z * (len * .32) });
        this.game.audio?.crash(impact);
        if (impact > 4) this.game.camShake = Math.max(this.game.camShake, Math.min(1, impact / 20));
      }
    }
  }

  animateWheels(dt) {
    const roll = this.speed * dt / (this.cfg.wheelR || .35);
    for (const w of this.wheels) {
      w.mesh.rotation.x += roll;
      if (w.front) w.mesh.rotation.y = this.steer * .42;
    }
  }

  animateLights(elapsed, night, controls) {
    const lightsOn = this.lightsOn || night > .5;
    if (lightsOn) this.lightsOn = true;
    const left = this.indicator === -1 || controls?.left;
    const right = this.indicator === 1 || controls?.right;
    setLightState(this.headMats, this.brakeMats, this.turnMats, {
      lightsOn: this.lightsOn,
      braking: this.brakeOn,
      left, right,
    });
    if (this.serviceLights) {
      const on = Math.floor(elapsed * 6) % 2 === 0;
      this.serviceLights.redM.color.setHex(on ? 0xff2020 : 0x280606);
      this.serviceLights.blueM.color.setHex(on ? 0x1b3fff : 0x080820);
      this.serviceLights.light.color.setHex(on ? 0xff2020 : 0x2a5bff);
      this.serviceLights.light.intensity = 3;
    }
  }

  applyDamage(amount, hitPos = null) {
    this.health = clamp(this.health - amount, 0, 100);
    this.damageFlash = 1;
    if (hitPos) {
      if (amount > 4) this.game.effects.sparksAt(hitPos.x, hitPos.y, hitPos.z, Math.min(24, amount));
      if (amount > 8) {
        this.deform(amount, hitPos);
        this.game.effects.debris(hitPos.x, hitPos.y, hitPos.z, Math.min(12, amount / 2));
      }
      if (amount > 22) this.game.effects.explosion(hitPos.x, hitPos.y, hitPos.z);
    }
    if (this.health <= 0 && !this.dead) {
      this.dead = true;
      this.engineOn = false;
      this.game.notify?.('Vehicle disabled — engine failure', 'bad');
    }
    if (this.serviceLights) this.serviceLights.group.visible = this.health > 30;
  }

  deform(amount, hitPos) {
    // push nearby body panel vertices inward for persistent visible damage
    const local = hitPos ? this.group.worldToLocal(new THREE.Vector3(hitPos.x, hitPos.y, hitPos.z)) : new THREE.Vector3(0, 0, 1);
    const panels = [];
    this.group.traverse(o => {
      if (o.isMesh && o.userData.panel && o.geometry) panels.push(o);
    });
    if (!panels.length) return;
    const m = panels[Math.floor(Math.random() * panels.length)];
    const g = m.geometry;
    const pos = g.attributes.position;
    const center = local.clone();
    const strength = Math.min(.28, amount * .008);
    for (let i = 0; i < pos.count; i++) {
      const vx = pos.getX(i), vy = pos.getY(i), vz = pos.getZ(i);
      const d = Math.hypot(vx - center.x, vy - center.y, vz - center.z);
      if (d < 2.5) {
        const f = (1 - d / 2.5) * strength;
        pos.setXYZ(i, vx * (1 - f * .5), vy * (1 - f * .7), vz * (1 - f * .3));
      }
    }
    pos.needsUpdate = true;
    g.computeVertexNormals();
    this.bodyMat.color.multiplyScalar(.985);
  }

  repair() {
    this.health = 100; this.fuel = this.cfg.fuel; this.engineOn = true; this.dead = false; this.visible = true;
    this.group.visible = true;
  }

  dispose() {
    this.game.scene.remove(this.group);
  }
}

export class VehicleManager {
  constructor(game) {
    this.game = game;
    this.vehicles = [];
    this.playerVehicle = null;
    this.trafficLimit = 34;
    this.spawnedTraffic = false;
    this.pendingTraffic = [];
  }

  spawn(type, x, z, heading = 0, opts = {}) {
    const v = new Vehicle(this.game, type, x, z, heading, opts);
    this.vehicles.push(v);
    return v;
  }

  spawnTraffic(count) {
    const types = ['sedan', 'sedan', 'taxi', 'suv', 'sports', 'van', 'pickup', 'bus', 'truck', 'suv', 'sedan'];
    const parked = this.vehicles.filter(v => v.mode === 'parked' || v.mode === 'traffic');
    for (let i = 0; i < count; i++) {
      const t = pick(types);
      const seg = this.randomRoadPoint();
      const v = this.spawn(t, seg.x, seg.z, seg.heading, { traffic: true, color: randomVehicleColor(t), y: .02 });
      v.traffic.cruise = t === 'bus' ? rand(7, 9) : t === 'truck' ? rand(7, 9) : rand(10, 14.5);
      this.vehicles.push;
    }
  }

  randomRoadPoint() {
    const i = 1 + Math.floor(Math.random() * 7);
    const j = 1 + Math.floor(Math.random() * 7);
    const vertical = Math.random() > .5;
    if (vertical) {
      const x = NODE_POS(i) + (Math.random() > .5 ? 4 : -4);
      const z = NODE_POS(j) + rand(10, 80) * (Math.random() > .5 ? 1 : -1);
      return { x, z, heading: z > NODE_POS(j) ? 0 : Math.PI, axis: 'z' };
    }
    const z = NODE_POS(j) + (Math.random() > .5 ? 4 : -4);
    const x = NODE_POS(i) + rand(10, 80) * (Math.random() > .5 ? 1 : -1);
    return { x, z, heading: x > NODE_POS(i) ? Math.PI / 2 : -Math.PI / 2, axis: 'x' };
  }

  spawnParkedCity() {
    const spots = [...this.game.city.parkingSpots].sort(() => Math.random() - .5).slice(0, 18);
    const types = ['sedan', 'suv', 'sports', 'van', 'pickup', 'sedan', 'taxi'];
    for (const s of spots) {
      this.spawn(pick(types), s.x, s.z, s.heading, { color: randomVehicleColor(pick(types)) });
    }
    // player starting car (owned)
    this.startCar = this.spawn('sedan', 4, 36, Math.PI, { color: 0x2b4a6f, owned: true, name: 'Your Sable' });
    // special services
    const police1 = this.spawn('police', 132, 44, Math.PI / 2, { service: 'police', color: 0xe8edf0 });
    const police2 = this.spawn('police', 132, 58, -Math.PI / 2, { service: 'police' });
    this.policeUnits = [police1, police2];
    this.ambulance = this.spawn('ambulance', 168, 166, Math.PI / 2, { service: 'ambulance' });
    this.fireEngine = this.spawn('fire', -150, -30, Math.PI / 2, { service: 'fire' });
    this.helipadHeli = this.spawn('helicopter', this.game.city.helipad.x, this.game.city.helipad.z, 0, { y: this.game.city.helipad.y + 1.7 });
    this.helipadHeli.altitude = this.helipadHeli.pos.y;
    this.boats = [
      this.spawn('boat', 300, 500, Math.PI, { y: .25 }),
      this.spawn('boat', 322, 510, Math.PI * .9, { y: .25, color: 0xbb3a34 }),
      this.spawn('boat', 345, 530, Math.PI, { y: .25, color: 0x2f6e8f }),
    ];
    this.supercars = [
      this.spawn('super', 30, 158, Math.PI / 2, { color: 0xe4c44a }),
      this.spawn('super', 36, 166, Math.PI / 2, { color: 0x1c1c22 }),
      this.spawn('sports', 24, 170, Math.PI / 2, { color: 0xb23434 }),
    ];
    this.bus = this.spawn('bus', 96, 340, 0, { color: 0x2c6f88 });
    this.construction = this.spawn('construction', -300, -300, Math.PI / 2, { color: 0xd6a51f });
  }

  findNearest(x, z, radius = 5, filter = null) {
    let best = null, bd = radius;
    for (const v of this.vehicles) {
      if (v.isPlayer) continue;
      if (filter && !filter(v)) continue;
      const d = Math.hypot(v.pos.x - x, v.pos.z - z);
      if (d < bd) { bd = d; best = v; }
    }
    return best ? { vehicle: best, dist: bd } : null;
  }

  startDriving(v) {
    this.playerVehicle = v;
    v.mode = 'player';
    v.isPlayer = true;
    v.traffic = null;
    v.parkedName = v.parkedName || v.cfg.name;
    v.engineOn = true;
    this.game.audio?.startEngine(v);
  }

  stopDriving(v) {
    if (!v) return;
    v.mode = 'parked';
    v.isPlayer = false;
    v.throttle = 0; v.brakeInput = 0; v.steer = 0; v.indicator = 0;
    this.playerVehicle = null;
    this.game.audio?.stopEngine();
  }

  update(dt, elapsed, night, weather) {
    const player = this.playerVehicle;
    if (player) {
      player.velocity && player.updatePlayer(dt, this.game.controls.vehicle, weather, elapsed, night);
    }
    for (const v of this.vehicles) {
      if (v === player) continue;
      if (v.mode === 'traffic') v.updateTraffic(dt, elapsed, night, weather);
      else {
        // keep service lights / smoke alive on parked damaged cars
        if (v.health < 55) this.game.effects.smokeAtVehicle(v, dt * .5);
        if (v.serviceLights) {
          const on = Math.floor(elapsed * 5) % 2 === 0;
          v.serviceLights.redM.color.setHex(on ? 0xff2020 : 0x280606);
          v.serviceLights.blueM.color.setHex(on ? 0x0b0b30 : 0x2a5bff);
          v.serviceLights.light.intensity = on ? 2.4 : 1.8;
        }
      }
    }
    if (player) this.handleTrafficCollisions(player);
  }

  handleTrafficCollisions(player) {
    const pf = { x: Math.sin(player.heading), z: Math.cos(player.heading) };
    for (const v of this.vehicles) {
      if (v === player || v.mode !== 'traffic') continue;
      const dx = v.pos.x - player.pos.x, dz = v.pos.z - player.pos.z;
      const d = Math.hypot(dx, dz);
      const minD = (v.cfg.len + player.cfg.len) * .38;
      if (d < minD && d > .01) {
        const nx = dx / d, nz = dz / d;
        const speed = Math.abs(player.speed);
        v.knock.set(nx * (2 + speed * .35), nz * (2 + speed * .35));
        v.knockTimer = .8;
        v.pos.x += nx * (minD - d) * .8; v.pos.z += nz * (minD - d) * .8;
        if (player.speed > 4) {
          player.velocity.multiplyScalar(.82);
          this.game.effects.sparksAt(v.pos.x, v.pos.y + .8, v.pos.z, 14);
          v.health = clamp(v.health - Math.min(30, speed * .8), 0, 100);
          this.game.audio?.crash(speed);
          this.game.camShake = Math.max(this.game.camShake, Math.min(.8, speed / 35));
          this.game.onTrafficCollision?.(player, v);
        }
      }
    }
  }

  nearestService(type, x, z) {
    let best = null, bd = Infinity;
    for (const v of this.vehicles) {
      if (v.service !== type) continue;
      const d = Math.hypot(v.pos.x - x, v.pos.z - z);
      if (d < bd) { bd = d; best = v; }
    }
    return best;
  }
}

import * as THREE from 'three';
import { clamp, lerp, lerpAngle, normAngle, TAU, formatMoney } from './utils.js';

export class Player {
  constructor(game) {
    this.game = game;
    this.group = new THREE.Group();
    this.group.name = 'player';
    game.scene.add(this.group);
    this.pos = new THREE.Vector3(10, 0.18, 34);
    this.heading = Math.PI;
    this.velocity = new THREE.Vector3();
    this.verticalVelocity = 0;
    this.onGround = true;
    this.groundY = 0.18;
    this.walkPhase = 0;
    this.moveAmount = 0;
    this.sprinting = false;
    this.crouching = false;
    this.firstPerson = false;
    this.cameraYaw = Math.PI;
    this.cameraPitch = 0.04;
    this.cameraDist = 5.2;
    this.cameraHeight = 1.55;
    this.camShake = 0;
    this.riding = null;
    this.interior = null;
    this.vehicle = null;
    this.visible = true;
    this.footTimer = 0;
    this.animT = 0;
    this.idleT = 0;
    this.clothing = { jacket: 0x27384d, pants: 0x222a33, shoes: 0x14181c, skin: 0xc08a63, hair: 0x2b211b };
    this.buildModel();
    this.group.position.copy(this.pos);
    this.group.rotation.y = this.heading;
    this.camera = game.camera;
    this.camera.position.set(0, 10, 20);
    this.tmp = new THREE.Vector3();
    this.wantToSit = false;
    this.cinematic = null;
  }

  buildModel() {
    const g = this.group;
    this.body = new THREE.Group();
    g.add(this.body);
    const skinMat = new THREE.MeshStandardMaterial({ color: this.clothing.skin, roughness: .72 });
    const jacketMat = new THREE.MeshStandardMaterial({ color: this.clothing.jacket, roughness: .82 });
    const pantsMat = new THREE.MeshStandardMaterial({ color: this.clothing.pants, roughness: .9 });
    const shoeMat = new THREE.MeshStandardMaterial({ color: this.clothing.shoes, roughness: .7 });
    const hairMat = new THREE.MeshStandardMaterial({ color: this.clothing.hair, roughness: .9 });
    this.mats = { skinMat, jacketMat, pantsMat, shoeMat, hairMat };

    const hips = new THREE.Group(); hips.position.y = .86; this.body.add(hips);
    const torso = new THREE.Mesh(new THREE.CapsuleGeometry(.22, .38, 4, 10), jacketMat);
    torso.position.y = .38; torso.castShadow = true; hips.add(torso);
    const chest = new THREE.Mesh(new THREE.BoxGeometry(.44, .22, .26), jacketMat); chest.position.y = .48; hips.add(chest);
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(.075, .085, .13, 8), skinMat); neck.position.y = .68; hips.add(neck);
    const head = new THREE.Mesh(new THREE.SphereGeometry(.175, 14, 12), skinMat); head.position.y = .82; head.castShadow = true; hips.add(head);
    const hair = new THREE.Mesh(new THREE.SphereGeometry(.181, 12, 10, 0, TAU, 0, Math.PI * .58), hairMat);
    hair.position.set(0, .845, -.006); hips.add(hair);
    // arms
    const armGeo = new THREE.CapsuleGeometry(.065, .4, 3, 8);
    this.armL = new THREE.Group(); this.armL.position.set(-.29, .56, 0); hips.add(this.armL);
    const armLMesh = new THREE.Mesh(armGeo, jacketMat); armLMesh.position.y = -.24; armLMesh.castShadow = true; this.armL.add(armLMesh);
    const handL = new THREE.Mesh(new THREE.SphereGeometry(.07, 8, 6), skinMat); handL.position.y = -.48; this.armL.add(handL);
    this.armR = new THREE.Group(); this.armR.position.set(.29, .56, 0); hips.add(this.armR);
    const armRMesh = new THREE.Mesh(armGeo, jacketMat); armRMesh.position.y = -.24; armRMesh.castShadow = true; this.armR.add(armRMesh);
    const handR = new THREE.Mesh(new THREE.SphereGeometry(.07, 8, 6), skinMat); handR.position.y = -.48; this.armR.add(handR);
    // legs
    const legGeo = new THREE.CapsuleGeometry(.085, .44, 3, 8);
    this.legL = new THREE.Group(); this.legL.position.set(-.12, .02, 0); hips.add(this.legL);
    const legLMesh = new THREE.Mesh(legGeo, pantsMat); legLMesh.position.y = -.27; legLMesh.castShadow = true; this.legL.add(legLMesh);
    const shoeL = new THREE.Mesh(new THREE.BoxGeometry(.17, .1, .3), shoeMat); shoeL.position.set(0, -.53, .05); this.legL.add(shoeL);
    this.legR = new THREE.Group(); this.legR.position.set(.12, .02, 0); hips.add(this.legR);
    const legRMesh = new THREE.Mesh(legGeo, pantsMat); legRMesh.position.y = -.27; legRMesh.castShadow = true; this.legR.add(legRMesh);
    const shoeR = new THREE.Mesh(new THREE.BoxGeometry(.17, .1, .3), shoeMat); shoeR.position.set(0, -.53, .05); this.legR.add(shoeR);
    this.hips = hips;
    // shadow blob
    const shadow = new THREE.Mesh(new THREE.CircleGeometry(.42, 16), new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: .24, depthWrite: false }));
    shadow.rotation.x = -Math.PI / 2; shadow.position.y = .012; g.add(shadow);
    this.shadow = shadow;
  }

  setClothing(c) {
    Object.assign(this.clothing, c);
    this.mats.jacketMat.color.setHex(this.clothing.jacket);
    this.mats.pantsMat.color.setHex(this.clothing.pants);
    this.mats.shoeMat.color.setHex(this.clothing.shoes);
    this.mats.hairMat.color.setHex(this.clothing.hair);
    this.mats.skinMat.color.setHex(this.clothing.skin);
  }

  setPosition(x, z, y = 0.18) {
    this.pos.set(x, y, z);
    this.groundY = y;
    this.group.position.copy(this.pos);
  }

  enteredVehicle(v) {
    this.vehicle = v;
    this.group.visible = false;
    this.shadow.visible = false;
    this.riding = null;
    this.cameraYaw = v.heading;
    this.cameraPitch = v.isAir ? .18 : .1;
    this.cameraDist = v.cfg.len > 6 ? 11 : v.cfg.len > 4.8 ? 7.4 : 5.6;
    if (v.isAir) this.cameraDist = 12;
  }

  exitVehicle(v, side = 1) {
    const fx = Math.sin(v.heading), fz = Math.cos(v.heading);
    const rx = -fz, rz = fx;
    const off = v.cfg.wid / 2 + 1.1;
    let x = v.pos.x + rx * off * side, z = v.pos.z + rz * off * side;
    // avoid placing inside a wall
    const hit = this.game.city.collideCircle(x, z, .5);
    if (hit) { x = v.pos.x - rx * off * side; z = v.pos.z - rz * off * side; }
    this.vehicle = null;
    this.group.visible = true;
    this.shadow.visible = true;
    this.setPosition(x, z, this.groundY || .18);
    this.heading = v.heading;
    this.group.rotation.y = this.heading;
    this.cameraYaw = v.heading;
    this.velocity.set(0, 0, 0);
  }

  toggleCamera() {
    this.firstPerson = !this.firstPerson;
    this.cameraDist = this.firstPerson ? 0 : (this.vehicle ? 7 : 5.2);
    this.group.visible = !this.firstPerson && !this.vehicle;
    this.shadow.visible = !this.firstPerson && !this.vehicle;
    return this.firstPerson;
  }

  updateCamera(dt) {
    const cam = this.camera;
    if (this.cinematic) {
      const c = this.cinematic;
      c.t += dt;
      const t = c.t;
      cam.position.set(c.cx + Math.sin(t * c.speed) * c.radius, c.cy + Math.sin(t * .3) * 12, c.cz + Math.cos(t * c.speed) * c.radius);
      cam.lookAt(0, 28, 0);
      return;
    }
    if (this.vehicle) {
      this.updateVehicleCamera(dt);
      return;
    }
    if (this.riding) {
      this.updateRidingCamera(dt);
      return;
    }
    const target = this.tmp.set(this.pos.x, this.pos.y + this.cameraHeight, this.pos.z);
    const yaw = this.cameraYaw, pitch = this.cameraPitch;
    let dist = this.cameraDist;
    if (this.firstPerson) {
      const eye = new THREE.Vector3(this.pos.x, this.pos.y + 1.62, this.pos.z);
      cam.position.lerp(eye, clamp(dt * 18, 0, 1));
      const dir = new THREE.Vector3(Math.sin(yaw) * Math.cos(pitch), Math.sin(-pitch), Math.cos(yaw) * Math.cos(pitch));
      cam.lookAt(eye.x + dir.x, eye.y + dir.y, eye.z + dir.z);
      cam.rotation.z = 0;
      return;
    }
    const back = new THREE.Vector3(-Math.sin(yaw) * Math.cos(pitch), Math.sin(pitch), -Math.cos(yaw) * Math.cos(pitch));
    let desired = new THREE.Vector3(target.x + back.x * dist, target.y + back.y * dist + 1.15, target.z + back.z * dist);
    // camera wall avoidance
    const hit = this.game.city.collideCircle(desired.x, desired.z, .45);
    if (hit) {
      desired.x += hit.nx * hit.pen * 1.2;
      desired.z += hit.nz * hit.pen * 1.2;
    }
    desired.y = Math.max(desired.y, .55);
    cam.position.lerp(desired, clamp(dt * 9, 0, 1));
    const look = new THREE.Vector3(this.pos.x, this.pos.y + 1.45, this.pos.z);
    cam.lookAt(look);
    // subtle shake
    if (this.game.camShake > 0) {
      const s = this.game.camShake;
      cam.position.x += (Math.random() - .5) * s * .25;
      cam.position.y += (Math.random() - .5) * s * .2;
      this.game.camShake = Math.max(0, s - dt * 2.2);
    }
  }

  updateVehicleCamera(dt) {
    const v = this.vehicle;
    const cam = this.camera;
    const yaw = v.heading + this.cameraYaw * 0; // vehicle camera orbit uses absolute yaw set by input
    const baseDist = v.isAir ? 13 : v.cfg.len > 6 ? 13 : v.cfg.len > 4.8 ? 9 : 7.2;
    const dist = this.cameraDist || baseDist;
    const pitch = this.cameraPitch;
    const target = new THREE.Vector3(v.pos.x, v.pos.y + (v.isAir ? 2 : v.cfg.height * .55), v.pos.z);
    if (this.firstPerson) {
      const eye = new THREE.Vector3(v.pos.x + Math.sin(v.heading) * v.cfg.len * .15, v.pos.y + (v.isAir ? 2.0 : v.cfg.height * .55), v.pos.z + Math.cos(v.heading) * v.cfg.len * .15);
      cam.position.lerp(eye, clamp(dt * 12, 0, 1));
      const dir = new THREE.Vector3(Math.sin(this.cameraYaw) * Math.cos(pitch), Math.sin(-pitch), Math.cos(this.cameraYaw) * Math.cos(pitch));
      cam.lookAt(eye.x + dir.x, eye.y + dir.y, eye.z + dir.z);
      return;
    }
    // orbit yaw = cameraYaw, but when moving it eases toward driving direction
    const drivingYaw = this.cameraYaw;
    const back = new THREE.Vector3(-Math.sin(drivingYaw) * Math.cos(pitch), Math.sin(pitch) * .6, -Math.cos(drivingYaw) * Math.cos(pitch));
    const desired = new THREE.Vector3(target.x + back.x * dist, target.y + Math.max(1.2, back.y * dist), target.z + back.z * dist);
    const hit = this.game.city.collideCircle(desired.x, desired.z, .45);
    if (hit) { desired.x += hit.nx * hit.pen; desired.z += hit.nz * hit.pen; }
    desired.y = Math.max(desired.y, v.isAir ? v.pos.y - 2 : .7);
    cam.position.lerp(desired, clamp(dt * 7, 0, 1));
    cam.lookAt(target);
    if (this.game.camShake > 0) {
      const s = this.game.camShake;
      cam.position.x += (Math.random() - .5) * s * .22;
      cam.position.y += (Math.random() - .5) * s * .18;
      this.game.camShake = Math.max(0, s - dt * 2.4);
    }
  }

  updateRidingCamera(dt) {
    const r = this.riding;
    const cam = this.camera;
    const t = r.group ? r.group.position : r.pos;
    const yaw = this.cameraYaw;
    const dist = this.cameraDist;
    const target = new THREE.Vector3(t.x, t.y + 2, t.z);
    const back = new THREE.Vector3(-Math.sin(yaw), 0, -Math.cos(yaw)).multiplyScalar(dist);
    const desired = new THREE.Vector3(target.x + back.x, target.y + 2.2 + Math.sin(this.cameraPitch) * dist, target.z + back.z);
    cam.position.lerp(desired, clamp(dt * 4, 0, 1));
    cam.lookAt(target);
  }

  update(dt, input) {
    if (this.cinematic) { this.updateCamera(dt); return; }
    if (this.vehicle) {
      this.updateCamera(dt);
      return;
    }
    if (this.riding) {
      this.updateCamera(dt);
      return;
    }
    // movement on foot
    const yaw = this.cameraYaw;
    let mx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    let mz = (input.forward ? 1 : 0) - (input.back ? 1 : 0);
    const mag = Math.hypot(mx, mz);
    if (mag > 0) { mx /= mag; mz /= mag; }
    const f = new THREE.Vector2(Math.sin(yaw), Math.cos(yaw));
    const r = new THREE.Vector2(-f.y, f.x);
    const sprint = input.sprint;
    const speed = this.crouching ? 2.1 : sprint ? 6.9 : 3.7;
    const targetVel = new THREE.Vector2(f.x * mz + r.x * mx, f.y * mz + r.y * mx).multiplyScalar(speed * (mag > 0 ? 1 : 0));
    const accel = this.onGround ? 16 : 5;
    this.velocity.x = lerp(this.velocity.x, targetVel.x, clamp(dt * accel, 0, 1));
    this.velocity.z = lerp(this.velocity.z, targetVel.y, clamp(dt * accel, 0, 1));
    if (mag > 0) {
      const moveHeading = Math.atan2(this.velocity.x, this.velocity.z);
      this.heading = lerpAngle(this.heading, moveHeading, clamp(dt * 11, 0, 1));
    }
    this.group.rotation.y = this.heading;
    const nextX = this.pos.x + this.velocity.x * dt;
    const nextZ = this.pos.z + this.velocity.z * dt;
    // collision
    let nx = nextX, nz = nextZ;
    const hit = this.game.city.collideCircle(nx, nz, .42);
    if (hit) {
      nx += hit.nx * hit.pen; nz += hit.nz * hit.pen;
      this.velocity.x *= .3; this.velocity.z *= .3;
    }
    // world bounds
    nx = clamp(nx, -660, 760);
    nz = clamp(nz, -660, 500);
    this.pos.x = nx; this.pos.z = nz;
    // jump / gravity
    if (input.jump && this.onGround) {
      this.verticalVelocity = 5.8;
      this.onGround = false;
      this.game.audio?.jump();
    }
    this.verticalVelocity -= 18 * dt;
    this.pos.y += this.verticalVelocity * dt;
    if (this.pos.y <= this.groundY) {
      this.pos.y = this.groundY;
      this.verticalVelocity = 0;
      this.onGround = true;
    }
    this.moveAmount = Math.hypot(this.velocity.x, this.velocity.z);
    this.sprinting = sprint && this.moveAmount > 4;
    this.group.position.copy(this.pos);
    this.animate(dt, this.moveAmount, sprint);
    // footsteps
    if (this.onGround && this.moveAmount > .5) {
      this.footTimer -= dt * (sprint ? 1.8 : 1.2);
      if (this.footTimer <= 0) { this.footTimer = .48; this.game.audio?.footstep(sprint); }
    }
    this.updateCamera(dt);
  }

  animate(dt, speed, sprint) {
    this.animT += dt;
    if (speed > .2) {
      this.walkPhase += dt * (sprint ? 12 : 7.5) * clamp(speed / 3.5, .5, 1.6);
      const swing = Math.sin(this.walkPhase) * (sprint ? .78 : .5);
      this.legL.rotation.x = swing;
      this.legR.rotation.x = -swing;
      this.armL.rotation.x = -swing * .8;
      this.armR.rotation.x = swing * .8;
      this.hips.position.y = .86 + Math.abs(Math.sin(this.walkPhase)) * (sprint ? .07 : .035);
      this.body.rotation.x = sprint ? -.14 : -.03;
    } else {
      this.idleT += dt;
      const idle = Math.sin(this.idleT * 1.6) * .02;
      this.legL.rotation.x = lerp(this.legL.rotation.x, 0, dt * 7);
      this.legR.rotation.x = lerp(this.legR.rotation.x, 0, dt * 7);
      this.armL.rotation.x = lerp(this.armL.rotation.x, -idle, dt * 6);
      this.armR.rotation.x = lerp(this.armR.rotation.x, idle, dt * 6);
      this.hips.position.y = .86 + idle * .2;
      this.body.rotation.x = lerp(this.body.rotation.x, 0, dt * 5);
    }
    // vertical bob / jump pose
    if (!this.onGround) {
      this.legL.rotation.x = .45; this.legR.rotation.x = -.25;
      this.armL.rotation.x = -.7; this.armR.rotation.x = -.7;
    }
    this.shadow.position.y = this.groundY - this.pos.y + .012;
    this.shadow.material.opacity = clamp(.26 - (this.pos.y - this.groundY) * .08, .05, .3);
  }

  beginCinematic(cx, cy, cz, radius, speed) {
    this.cinematic = { cx, cy, cz, radius, speed, t: 0 };
    this.group.visible = false;
  }

  endCinematic() {
    this.cinematic = null;
    this.group.visible = !this.vehicle && !this.firstPerson;
  }
}

import * as THREE from 'three';
import { clamp, lerp, lerpAngle, normAngle, rand, pick, chance, TAU, formatMoney } from './utils.js';
import { NODE_POS, GRID, SPACING } from './city.js';

const SKIN = [0xc08a63, 0x8c5c3c, 0xe0b28c, 0x6b4230, 0xa8724f, 0xd9a07a, 0x5c3826];
const JACKETS = [0x2b3a4d, 0x6b2d35, 0x344a3a, 0x51465c, 0x23262c, 0x8c6b3d, 0xa8b0b5, 0x3e5f80, 0x7a3e52, 0x4d5547];
const PANTS = [0x222a33, 0x2c2f36, 0x3b3b40, 0x4a4136, 0x22262c, 0x5a5d60, 0x1b2026];
const HAIR = [0x1e1611, 0x3b2a1d, 0x6a4a2c, 0x9a7a4a, 0x151515, 0x777777];

export class PedestrianSystem {
  constructor(game) {
    this.game = game;
    this.count = 140;
    this.peds = [];
    this.parts = {};
    this.dummy = new THREE.Object3D();
    this.local = new THREE.Object3D();
    this.mat4 = new THREE.Matrix4();
    this.initMeshes();
    this.spawn();
    this.scanTimer = 0;
  }

  initMeshes() {
    const capacity = this.count;
    const geo = {
      torso: new THREE.BoxGeometry(.42, .64, .26),
      head: new THREE.SphereGeometry(.172, 10, 8),
      legL: new THREE.BoxGeometry(.15, .72, .18),
      legR: new THREE.BoxGeometry(.15, .72, .18),
      armL: new THREE.BoxGeometry(.13, .62, .15),
      armR: new THREE.BoxGeometry(.13, .62, .15),
      hair: new THREE.SphereGeometry(.177, 8, 6, 0, TAU, 0, Math.PI * .55),
    };
    const white = new THREE.MeshStandardMaterial({ vertexColors: false, roughness: .85 });
    this.meshMats = {
      torso: new THREE.MeshStandardMaterial({ roughness: .85 }),
      head: new THREE.MeshStandardMaterial({ roughness: .7 }),
      leg: new THREE.MeshStandardMaterial({ roughness: .9 }),
      arm: new THREE.MeshStandardMaterial({ roughness: .85 }),
      hair: new THREE.MeshStandardMaterial({ roughness: .93 }),
    };
    for (const k of Object.keys(geo)) {
      const mesh = new THREE.InstancedMesh(geo[k], this.meshMats[k === 'head' || k === 'hair' ? 'head' : k.startsWith('leg') ? 'leg' : k.startsWith('arm') ? 'arm' : k === 'hair' ? 'hair' : 'torso'], capacity);
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      mesh.castShadow = k !== 'hair';
      mesh.frustumCulled = false;
      this.game.scene.add(mesh);
      this.parts[k] = mesh;
    }
    // per instance colors
    for (const ped of []) {}
    for (const mesh of Object.values(this.parts)) {
      for (let i = 0; i < capacity; i++) mesh.setColorAt(i, new THREE.Color(0xffffff));
      mesh.instanceColor.needsUpdate = true;
    }
  }

  colorFor(ped) {
    const c = new THREE.Color();
    for (let i = 0; i < this.count; i++) {
      const p = this.peds[i];
      if (!p) continue;
      this.parts.torso.setColorAt(i, new THREE.Color(p.colors.jacket));
      this.parts.armL.setColorAt(i, new THREE.Color(p.colors.jacket));
      this.parts.armR.setColorAt(i, new THREE.Color(p.colors.jacket));
      this.parts.head.setColorAt(i, new THREE.Color(p.colors.skin));
      this.parts.hair.setColorAt(i, new THREE.Color(p.colors.hair));
      this.parts.legL.setColorAt(i, new THREE.Color(p.colors.pants));
      this.parts.legR.setColorAt(i, new THREE.Color(p.colors.pants));
    }
    for (const mesh of Object.values(this.parts)) mesh.instanceColor.needsUpdate = true;
  }

  spawn() {
    const c = this.game.city;
    for (let i = 0; i < this.count; i++) {
      let ped;
      if (i < 22) ped = this.makeCrosser(i);
      else if (i < 34) ped = this.makeIdler(i);
      else ped = this.makeWalker(i);
      ped.index = i;
      ped.colors = { jacket: pick(JACKETS), pants: pick(PANTS), skin: pick(SKIN), hair: pick(HAIR) };
      ped.scale = rand(.9, 1.06);
      ped.phase = rand(0, TAU);
      ped.speed = rand(.85, 1.5);
      ped.idleTimer = rand(0, 3);
      ped.state = ped.type === 'idler' ? 'idle' : 'walk';
      ped.fleeTimer = 0;
      ped.downTimer = 0;
      ped.talkTimer = 0;
      ped.pos = new THREE.Vector3(ped.x, .18, ped.z);
      ped.heading = rand(0, TAU);
      this.peds.push(ped);
    }
    this.colorFor();
  }

  randomSidewalkPoint() {
    const vertical = Math.random() > .5;
    const line = Math.floor(Math.random() * GRID);
    const dir = Math.random() > .5 ? 1 : -1;
    const start = 1 + Math.floor(Math.random() * 6);
    const offset = Math.random() > .5 ? 9.3 : 9.3;
    if (vertical) {
      const x = NODE_POS(line) - dir * offset;
      const z = NODE_POS(start) + rand(4, 60);
      return { x, z, axis: 'z', line, dir, i: line, j: start, t: rand(4, 60) };
    }
    const z = NODE_POS(line) + dir * offset;
    const x = NODE_POS(start) + rand(4, 60);
    return { x, z, axis: 'x', line, dir, i: start, j: line, t: rand(4, 60) };
  }

  makeWalker(i) {
    const p = this.randomSidewalkPoint();
    return {
      type: 'walker', x: p.x, z: p.z, axis: p.axis, dir: p.dir, line: p.line,
      ni: p.i, nj: p.j, t: p.t, wait: 0, crossing: false,
    };
  }

  makeCrosser(i) {
    const vertical = Math.random() > .5;
    const line = 1 + Math.floor(Math.random() * 7);
    const node = 1 + Math.floor(Math.random() * 7);
    const side = Math.random() > .5 ? 1 : -1;
    const axis = vertical ? 'x' : 'z';
    const x = vertical ? NODE_POS(node) - side * 9.3 : NODE_POS(line) + rand(-6, 6);
    const z = vertical ? NODE_POS(line) + rand(-2, 2) + 10.4 : NODE_POS(node) + side * 9.3;
    return {
      type: 'crosser', x, z, axis, line, dir: side, ni: node, nj: line,
      startX: x, startZ: z, t: 0, wait: 0, crossing: true, side,
      originNode: node, originLine: line, crossVertical: vertical,
    };
  }

  makeIdler(i) {
    const park = { x: -24, z: -24 };
    const a = rand(0, TAU), r = rand(4, 28);
    return {
      type: 'idler', x: park.x + Math.cos(a) * r, z: park.z + Math.sin(a) * r,
      axis: 'z', line: 4, dir: 1, ni: 4, nj: 4, t: 0, wait: rand(2, 12), home: true,
    };
  }

  nextWalkerTarget(p) {
    // choose a new direction at the upcoming node
    const options = [];
    for (const d of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      if (d[0] === -p.dir && p.axis === 'x') continue;
      if (d[1] === -p.dir && p.axis === 'z') continue;
      const ni = p.ni + d[0], nj = p.nj + d[1];
      if (ni < 0 || ni > GRID - 1 || nj < 0 || nj > GRID - 1) continue;
      options.push(d);
    }
    if (!options.length) {
      p.dir = -p.dir;
      return;
    }
    const straight = options.find(d => (p.axis === 'x' ? d[0] === p.dir : d[1] === p.dir));
    let chosen;
    if (straight && Math.random() < .68) chosen = straight;
    else chosen = pick(options);
    if (chosen[0] !== 0) { p.axis = 'x'; p.dir = chosen[0]; p.ni = p.ni + chosen[0]; }
    else { p.axis = 'z'; p.dir = chosen[1]; p.nj = p.nj + chosen[1]; }
    p.t = 0;
    p.wait = Math.random() < .2 ? rand(1, 4) : 0;
    p.line = p.axis === 'z' ? p.ni : p.nj;
  }

  targetPoint(p) {
    const off = 9.3;
    if (p.axis === 'z') {
      const x = NODE_POS(p.ni) - p.dir * off;
      const z = NODE_POS(p.nj) + p.dir * p.t;
      return { x, z };
    }
    const z = NODE_POS(p.nj) + p.dir * off;
    const x = NODE_POS(p.ni) + p.dir * p.t;
    return { x, z };
  }

  update(dt, elapsed, player) {
    const px = player.pos.x, pz = player.pos.z;
    const pv = player.vehicle;
    for (const p of this.peds) {
      const dx = p.x - px, dz = p.z - pz;
      const distToPlayer = Math.hypot(dx, dz);
      if (p.state === 'down') {
        p.downTimer -= dt;
        if (p.downTimer <= 0) { p.state = 'walk'; p.x += rand(-1, 1); p.z += rand(-1, 1); }
        this.writePed(p, elapsed, dt, true);
        continue;
      }
      // flee from nearby fast vehicles / danger
      if (p.fleeTimer > 0) {
        p.fleeTimer -= dt;
        p.x += Math.sin(p.heading) * 5.2 * dt;
        p.z += Math.cos(p.heading) * 5.2 * dt;
        p.state = 'flee';
        p.phase += dt * 16;
        this.writePed(p, elapsed, dt);
        continue;
      }
      const nearestVehicle = this.game.vehicles?.playerVehicle;
      if (nearestVehicle) {
        const vd = Math.hypot(nearestVehicle.pos.x - p.x, nearestVehicle.pos.z - p.z);
        if (vd < 9 && Math.abs(nearestVehicle.speed) > 4.5) {
          p.heading = Math.atan2(p.x - nearestVehicle.pos.x, p.z - nearestVehicle.pos.z);
          p.fleeTimer = rand(1.2, 2.4);
          if (Math.random() < .2) this.game.notify?.('Pedestrians scatter from the road', 'warn');
          continue;
        }
      }
      if (p.type === 'crosser') {
        this.updateCrosser(p, dt, elapsed);
      } else if (p.type === 'idler') {
        p.wait -= dt;
        if (p.wait <= 0) {
          p.wait = rand(2, 7);
          if (Math.random() < .45 && p.home) {
            // wander a little in the park
            const park = { x: -24, z: -24 };
            const a = rand(0, TAU), r = rand(4, 28);
            p.tx = park.x + Math.cos(a) * r; p.tz = park.z + Math.sin(a) * r; p.state = 'walk';
          } else p.state = 'idle';
        }
        if (p.state === 'walk' && p.tx !== undefined) {
          const d = Math.hypot(p.tx - p.x, p.tz - p.z);
          if (d > .4) {
            const h = Math.atan2(p.tx - p.x, p.tz - p.z);
            p.heading = lerpAngle(p.heading, h, dt * 5);
            p.x += Math.sin(p.heading) * 1.1 * dt; p.z += Math.cos(p.heading) * 1.1 * dt;
            p.phase += dt * 6;
          } else { p.state = 'idle'; p.wait = rand(2, 8); }
        }
      } else {
        this.updateWalker(p, dt);
      }
      // idle pause
      if (p.wait > 0) {
        p.wait -= dt;
        p.phase = lerp(p.phase, 0, dt);
        if (Math.random() < .002) p.heading += rand(-.5, .5);
        this.writePed(p, elapsed, dt);
        continue;
      }
      if (p.state === 'walk' || p.state === 'flee') {
        p.phase += dt * (p.type === 'crosser' ? 8 : 7) * (p.fleeTimer > 0 ? 1.6 : 1);
        p.x += Math.sin(p.heading) * p.speed * dt;
        p.z += Math.cos(p.heading) * p.speed * dt;
      } else if (p.state === 'idle') {
        p.phase += dt * .8;
      }
      this.writePed(p, elapsed, dt);
    }
    // periodic vehicle collision with people
    this.scanTimer -= dt;
    if (this.scanTimer <= 0) {
      this.scanTimer = .18;
      this.checkVehicleHits();
    }
  }

  updateWalker(p, dt) {
    const target = this.targetPoint(p);
    const dx = target.x - p.x, dz = target.z - p.z;
    const d = Math.hypot(dx, dz);
    p.heading = lerpAngle(p.heading, Math.atan2(dx, dz), dt * 4.5);
    p.state = 'walk';
    p.t += p.speed * dt * .72;
    if (p.t > 96) {
      p.t = 0;
      this.nextWalkerTarget(p);
    }
    // collision avoid buildings (sidewalk is safe)
  }

  updateCrosser(p, dt) {
    const target = p.crossing ? (p.axis === 'x' ? p.x > p.startX ? p.startX - 22 : p.startX + 22 : p.z > p.startZ ? p.startZ - 22 : p.startZ + 22) : null;
    if (p.crossing) {
      const xx = p.axis === 'x' ? target : p.startX + rand(-.2, .2);
      const zz = p.axis === 'x' ? p.startZ + rand(-.2, .2) : target;
      const dx = xx - p.x, dz = zz - p.z;
      const d = Math.hypot(dx, dz);
      p.heading = lerpAngle(p.heading, Math.atan2(dx, dz), dt * 7);
      p.state = 'walk';
      p.x += Math.sin(p.heading) * 1.65 * dt;
      p.z += Math.cos(p.heading) * 1.65 * dt;
      if (d < .6) { p.crossing = false; p.wait = rand(2, 8); p.startX = p.x; p.startZ = p.z; p.side = -p.side; }
    } else {
      p.wait -= dt;
      if (p.wait <= 0) { p.crossing = true; }
    }
  }

  writePed(p, elapsed, dt, downed = false) {
    const idx = p.index;
    const y = .18;
    this.dummy.position.set(p.x, y, p.z);
    this.dummy.rotation.set(0, p.heading, 0);
    if (downed) { this.dummy.rotation.z = Math.PI / 2; this.dummy.position.y = .3; }
    this.dummy.updateMatrix();
    const swing = Math.sin(p.phase) * .55;
    const armSwing = -swing * .75;
    const sc = p.scale;
    const parts = this.parts;
    const local = this.local;
    const m = this.mat4;
    const set = (mesh, lx, ly, lz, rx = 0, ry = 0, rz = 0, sx = sc, sy = sc, sz = sc) => {
      local.position.set(lx, ly, lz); local.rotation.set(rx, ry, rz); local.scale.set(sx, sy, sz); local.updateMatrix();
      m.multiplyMatrices(this.dummy.matrix, local.matrix);
      mesh.setMatrixAt(idx, m);
    };
    if (downed) {
      set(parts.torso, 0, 1.1, 0); set(parts.head, 0, 1.6, 0); set(parts.hair, 0, 1.62, 0);
      set(parts.armL, -.3, 1.32, 0, .3); set(parts.armR, .3, 1.32, 0, -.3);
      set(parts.legL, -.12, .52, .1); set(parts.legR, .12, .52, -.1);
    } else {
      const sitting = p.state === 'idle' && p.type === 'idler' && p.wait > 0 && Math.random() < 0;
      const hipY = .88 * sc;
      set(parts.torso, 0, 1.18 * sc, 0);
      set(parts.head, 0, 1.66 * sc, 0);
      set(parts.hair, 0, 1.674 * sc, -.005);
      set(parts.legL, -.12 * sc, .44 * sc, Math.sin(p.phase) * .24 * sc, Math.sin(p.phase) * .5);
      set(parts.legR, .12 * sc, .44 * sc, -Math.sin(p.phase) * .24 * sc, -Math.sin(p.phase) * .5);
      set(parts.armL, -.3 * sc, 1.28 * sc, -Math.sin(p.phase) * .2 * sc, armSwing);
      set(parts.armR, .3 * sc, 1.28 * sc, Math.sin(p.phase) * .2 * sc, -armSwing);
    }
    for (const mesh of Object.values(parts)) mesh.instanceMatrix.needsUpdate = true;
  }

  checkVehicleHits() {
    const pv = this.game.vehicles?.playerVehicle;
    if (!pv) return;
    if (Math.abs(pv.speed) < 2) return;
    const len = pv.cfg.len;
    const f = { x: Math.sin(pv.heading), z: Math.cos(pv.heading) };
    for (const p of this.peds) {
      if (p.state === 'down') continue;
      const rx = p.x - pv.pos.x, rz = p.z - pv.pos.z;
      const along = rx * f.x + rz * f.z;
      const side = Math.abs(rx * f.z - rz * f.x);
      if (Math.abs(along) < len * .55 && side < pv.cfg.wid * .55) {
        p.state = 'down'; p.downTimer = rand(5, 8);
        p.heading = pv.heading + rand(-1, 1);
        this.game.onPedHit?.(p, pv);
      }
    }
  }

  anyInFront(x, z, heading, dist) {
    const fx = Math.sin(heading), fz = Math.cos(heading);
    for (const p of this.peds) {
      if (p.state === 'down') continue;
      const dx = p.x - x, dz = p.z - z;
      if (Math.abs(dx) > dist || Math.abs(dz) > dist) continue;
      const d = Math.hypot(dx, dz);
      if (d < dist && (dx * fx + dz * fz) / Math.max(d, .001) > .55) return p;
    }
    return null;
  }

  nearest(x, z, radius = 3) {
    let best = null, bd = radius;
    for (const p of this.peds) {
      if (p.state === 'down') continue;
      const d = Math.hypot(p.x - x, p.z - z);
      if (d < bd) { bd = d; best = p; }
    }
    return best;
  }

  panic(x, z, radius = 25) {
    for (const p of this.peds) {
      if (Math.hypot(p.x - x, p.z - z) < radius) {
        p.fleeTimer = rand(2, 4);
        p.heading = Math.atan2(p.x - x, p.z - z);
      }
    }
  }

  gather(x, z, radius = 18) {
    for (const p of this.peds) {
      if (this.peds.indexOf(p) % 5 !== 0) continue;
      if (Math.hypot(p.x - x, p.z - z) < radius) {
        const a = rand(0, TAU), r = rand(4, 12);
        p.tx = x + Math.cos(a) * r; p.tz = z + Math.sin(a) * r; p.state = 'walk'; p.wait = 0;
        p.heading = Math.atan2(p.tx - p.x, p.tz - p.z);
      }
    }
  }
}

