87:   const d2 = dx * dx + dz * dz;
88:   if (d2 >= r * r) return null;
89:   const d = Math.sqrt(d2);
90:   if (d < 1e-5) {
91:     const left = x - box.minX, right = box.maxX - x, top = z - box.minZ, bottom = box.maxZ - z;
92:     const m = Math.min(left, right, top, bottom);
93:     if (m === left) return { nx: -1, nz: 0, pen: r + left };
94:     if (m === right) return { nx: 1, nz: 0, pen: r + right };
95:     if (m === top) return { nx: 0, nz: -1, pen: r + top };
