156:   buildRoads() {
157:     const mat = this.mats.asphalt;
158:     const geo = this.roadPlaneGeometry();
159:     this.roadMeshes = [];
160:     for (let i = 0; i < GRID; i++) {
161:       const p = NODE_POS(i);
162:       const v = new THREE.Mesh(geo, mat);
163:       v.position.set(p, 0.02, 0);
164:       v.receiveShadow = true;
165:       this.root.add(v); this.roadMeshes.push(v);
166:       const h = new THREE.Mesh(geo, mat);
167:       h.rotation.y = Math.PI / 2;
168:       h.position.set(0, 0.021, p);
169:       h.receiveShadow = true;
170:       this.root.add(h); this.roadMeshes.push(h);
171:     }
172:     // intersections
173:     const ig = new THREE.PlaneGeometry(ROAD_W, ROAD_W); ig.rotateX(-Math.PI / 2);
174:     const im = new THREE.MeshStandardMaterial({ color: 0x23262b, roughness: 0.93 });
175:     for (let i = 0; i < GRID; i++) for (let j = 0; j < GRID; j++) {
176:       const m = new THREE.Mesh(ig, im);
177:       m.position.set(NODE_POS(i), 0.035, NODE_POS(j));
178:       this.root.add(m);
179:     }
180: 
181:     // lane dashes
182:     const dashGeo = new THREE.BoxGeometry(0.16, 0.012, 3.2);
183:     const dashMat = new THREE.MeshStandardMaterial({ color: 0xd9d6c4, roughness: 0.8 });
184:     const dashes = [];
185:     for (let i = 0; i < GRID; i++) {
186:       for (let s = -CITY_EXTENT - 10; s < CITY_EXTENT + 10; s += 8) {
187:         if (Math.abs(((s + 4 + 48) % 96 + 96) % 96 - 48) < 10) continue;
188:         dashes.push([NODE_POS(i), s, 0]);
189:         dashes.push([s, NODE_POS(i), Math.PI / 2]);
190:       }
191:     }
192:     const dMesh = new THREE.InstancedMesh(dashGeo, dashMat, dashes.length);
193:     const tmp = new THREE.Object3D();
194:     dashes.forEach(([x, z, r], k) => {
195:       tmp.position.set(x, 0.055, z); tmp.rotation.set(0, r, 0); tmp.updateMatrix();
196:       dMesh.setMatrixAt(k, tmp.matrix);
197:     });
198:     dMesh.instanceMatrix.needsUpdate = true;
199:     this.root.add(dMesh);
200: 
201:     // crosswalks
202:     const cwGeo = new THREE.BoxGeometry(0.72, 0.014, 3.5);
203:     const cwMat = new THREE.MeshStandardMaterial({ color: 0xe9e7df, roughness: 0.75 });
204:     const cws = [];
205:     for (let i = 0; i < GRID; i++) for (let j = 0; j < GRID; j++) {
206:       const x = NODE_POS(i), z = NODE_POS(j);
207:       for (let a = -3; a <= 3; a++) {
208:         cws.push([x + a * 1.1, z - HALF_ROAD - 2.1, 0]);
209:         cws.push([x + a * 1.1, z + HALF_ROAD + 2.1, 0]);
210:         cws.push([x - HALF_ROAD - 2.1, z + a * 1.1, Math.PI / 2]);
211:         cws.push([x + HALF_ROAD + 2.1, z + a * 1.1, Math.PI / 2]);
212:       }
213:     }
214:     const cwMesh = new THREE.InstancedMesh(cwGeo, cwMat, cws.length);
215:     cws.forEach(([x, z, r], k) => {
216:       tmp.position.set(x, 0.06, z); tmp.rotation.set(0, r, 0); tmp.updateMatrix();
217:       cwMesh.setMatrixAt(k, tmp.matrix);
218:     });
219:     this.root.add(cwMesh);
220: 
221:     // edge lines
222:     const edgeGeo = new THREE.PlaneGeometry(0.14, 840); edgeGeo.rotateX(-Math.PI / 2);
223:     const edgeMat = new THREE.MeshStandardMaterial({ color: 0xc9c6b7, roughness: 0.85 });
224:     for (let i = 0; i < GRID; i++) {
225:       for (const side of [-1, 1]) {
226:         const v = new THREE.Mesh(edgeGeo, edgeMat);
227:         v.position.set(NODE_POS(i) + side * (HALF_ROAD - 0.45), 0.05, 0);
228:         this.root.add(v);
229:         const h = new THREE.Mesh(edgeGeo, edgeMat);
230:         h.rotation.y = Math.PI / 2;
231:         h.position.set(0, 0.05, NODE_POS(i) + side * (HALF_ROAD - 0.45));
232:         this.root.add(h);
233:       }
234:     }
235:   }
