295:   districtForBlock(bi, bj, special) {
296:     if (special === 'park') return 'park';
297:     if (special === 'suburb') return 'suburb';
298:     if (special === 'industrial') return 'industrial';
299:     if (special === 'airport') return 'airport';
300:     if (bj <= 1) return 'industrial';
301:     if (bi >= 6 && bj >= 2 && bj <= 5) return 'suburb';
302:     if (bj >= 6) return 'waterfront';
303:     if (bi <= 2 && bj >= 3) return 'residential';
304:     if (bi >= 3 && bi <= 5 && bj >= 2 && bj <= 5) return 'downtown';
305:     return 'midtown';
306:   }
307: 
308:   buildBlockContent(block, rng) {
309:     const { bi, bj, x, z, district, special } = block;
310:     if (special === 'park') { this.buildPark(block, rng); return; }
311:     if (special === 'hospital') { this.buildHospital(block); return; }
312:     if (special === 'police') { this.buildPolice(block); return; }
313:     if (special === 'fire') { this.buildFireStation(block); return; }
314:     if (special === 'garage') { this.buildGarage(block); return; }
315:     if (special === 'dealership') { this.buildDealership(block); return; }
316:     if (special === 'apartment') { this.buildApartment(block); return; }
317:     if (special === 'shop') { this.buildShop(block); return; }
318:     if (special === 'office') { this.buildOffice(block); return; }
319:     if (special === 'hotel') { this.buildHotel(block); return; }
320:     if (special === 'industrial') { this.buildFactory(block, rng); return; }
321:     if (district === 'downtown') this.buildDowntown(block, rng);
322:     else if (district === 'industrial') this.buildIndustrial(block, rng);
323:     else if (district === 'suburb') this.buildSuburb(block, rng);
324:     else if (district === 'waterfront') this.buildWaterfront(block, rng);
325:     else this.buildMidrise(block, rng);
326:   }
