349:   addBuilding(x, z, w, d, h, palette, variant, opts = {}) {
350:     const mat = this.buildingMaterial(palette, variant);
351:     const roof = opts.roofMat || this.roofMat;
352:     const geo = this.facadeGeometry(w, h, d);
353:     const mesh = new THREE.Mesh(geo, [mat, mat, roof, roof, mat, mat]);
354:     mesh.position.set(x, h / 2 + 0.15 + (opts.base || 0), z);
355:     mesh.castShadow = h > 14;
356:     mesh.receiveShadow = true;
357:     this.root.add(mesh);
358:     const collider = { minX: x - w / 2, maxX: x + w / 2, minZ: z - d / 2, maxZ: z + d / 2, height: h, type: 'building', mesh };
359:     this.colliders.push(collider);
360:     if (opts.extraColliders) {
361:       for (const c of opts.extraColliders) this.colliders.push(c);
362:     }
363:     return { mesh, collider };
364:   }
