366:   addRoofDetails(x, z, w, d, topY, rng, kind = 'normal') {
367:     const g = new THREE.Group();
368:     g.position.set(x, topY, z);
369:     const boxCount = 1 + Math.floor(rng() * 3);
370:     for (let i = 0; i < boxCount; i++) {
371:       const bw = 1.4 + rng() * 2.6, bh = 0.7 + rng() * 1.5, bd = 1.4 + rng() * 2.4;
372:       const m = new THREE.Mesh(new THREE.BoxGeometry(bw, bh, bd), rng() > .5 ? this.metalMat : this.concreteMat);
373:       m.position.set((rng() - .5) * (w - bw - 2), bh / 2 + 0.15, (rng() - .5) * (d - bd - 2));
374:       m.castShadow = true; g.add(m);
375:     }
376:     if (kind === 'tower') {
377:       const spire = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.22, 8 + rng() * 12, 5), this.metalMat);
378:       spire.position.y = 4 + rng() * 4; g.add(spire);
379:       const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.26, 6, 6), this.warmMat);
380:       beacon.position.y = spire.position.y + spire.geometry.parameters.height / 2; g.add(beacon);
381:       this.animated.push({ type: 'beacon', mesh: beacon, phase: rng() * 6 });
382:     }
383:     if (kind === 'tower' && rng() > 0.5) {
384:       const crown = new THREE.Mesh(new THREE.BoxGeometry(w * 0.92, 0.45, d * 0.92), this.crownMat);
385:       crown.position.y = 0.35; g.add(crown);
386:     }
387:     if (rng() > 0.55) {
388:       const ac = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.8, 1.4), this.whiteMat);
389:       ac.position.set((rng() - .5) * w * .5, 0.55, (rng() - .5) * d * .5); g.add(ac);
390:     }
391:     this.root.add(g);
392:     return g;
393:   }
