431:   buildMidrise(block, rng) {
432:     const { x, z } = block;
433:     const rows = rng() > .5 ? 2 : 1;
434:     for (let r = 0; r < rows; r++) {
435:       const w = 20 + rng() * 16, d = 18 + rng() * 14, h = 12 + rng() * 24;
436:       const bx = x + (rows === 2 ? (r - .5) * 30 : (rng() - .5) * 24);
437:       const bz = z + (rng() - .5) * (66 - d - 4);
438:       this.addBuilding(bx, bz, w, d, h, 'midrise', Math.floor(rng() * 4));
439:       this.addRoofDetails(bx, bz, w, d, h + .2, rng);
440:       if (rng() > .6) this.addBalconies(bx, bz, w, d, h, rng);
441:     }
442:   }
