444:   addBalconies(x, z, w, d, h, rng) {
445:     const mat = new THREE.MeshStandardMaterial({ color: 0x5b5b58, roughness: .9 });
446:     const count = Math.floor((h - 4) / 4);
447:     const geo = new THREE.BoxGeometry(w * .55, .18, .9);
448:     for (let i = 0; i < count; i++) {
449:       const y = 4.5 + i * 4;
450:       if (y > h - 1) break;
451:       const m = new THREE.Mesh(geo, mat);
452:       m.position.set(x, y, z + d / 2 + .45); this.root.add(m);
453:       const rail = new THREE.Mesh(new THREE.BoxGeometry(w * .55, .7, .06), this.glassMat);
454:       rail.position.set(x, y + .45, z + d / 2 + .88); this.root.add(rail);
455:     }
456:   }
