462:     for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) {
463:       const hx = x + (i - .5) * 31, hz = z + (j - .5) * 31;
464:       const w = 12 + rng() * 4, d = 10 + rng() * 4;
465:       const h = 3.6 + rng() * 2.4;
466:       const pal = Math.floor(rng() * 4);
467:       this.addBuilding(hx, hz, w, d, h, 'suburb', pal);
468:       // roof
469:       const roof = new THREE.Mesh(new THREE.ConeGeometry(1, 1, 4), new THREE.MeshStandardMaterial({ color: [0x5b4237, 0x4a4a4a, 0x6b3d36, 0x454b48][pal], roughness: .92 }));
470:       roof.rotation.y = Math.PI / 4;
471:       roof.scale.set(w * .78, 2.6 + rng() * 1.2, d * .78);
472:       roof.position.set(hx, h + 1.45, hz);
473:       roof.castShadow = true;
474:       this.root.add(roof);
475:       // porch
476:       const porch = new THREE.Mesh(new THREE.BoxGeometry(3.2, .22, 2.2), this.woodMat);
477:       porch.position.set(hx + (rng() - .5) * 2, .55, hz + d / 2 + .9); this.root.add(porch);
478:       // garden
479:       const garden = new THREE.Mesh(new THREE.PlaneGeometry(10, 8), new THREE.MeshStandardMaterial({ color: 0x415d32, roughness: 1 }));
480:       garden.rotation.x = -Math.PI / 2; garden.position.set(hx + 8, .17, hz + 7); this.root.add(garden);
481:       // fence
482:       const fenceMat = this.woodMat;
483:       for (let f = 0; f < 5; f++) {
484:         const post = new THREE.Mesh(new THREE.BoxGeometry(.16, .9, .16), fenceMat);
485:         post.position.set(hx + 3, .6, hz + 11 + f * 1.4); this.root.add(post);
486:       }
487:       // driveway
488:       const drive = new THREE.Mesh(new THREE.PlaneGeometry(4, 12), new THREE.MeshStandardMaterial({ color: 0x77756e, roughness: 1 }));
489:       drive.rotation.x = -Math.PI / 2; drive.position.set(hx + 5, .16, hz + 8); this.root.add(drive);
490:       if (rng() > .6) this.tree(hx + 10, hz + 9, .8 + rng() * .4);
491:     }
