494:   buildIndustrial(block, rng) {
495:     const { x, z } = block;
496:     const w = 44 + rng() * 12, d = 30 + rng() * 16, h = 8 + rng() * 6;
497:     const bx = x + (rng() - .5) * 8, bz = z + (rng() - .5) * 8;
498:     this.addBuilding(bx, bz, w, d, h, 'industrial', Math.floor(rng() * 3), { roofMat: this.roofMatDark });
499:     this.addRoofDetails(bx, bz, w, d, h + .2, rng);
500:     // loading dock
501:     const dock = new THREE.Mesh(new THREE.BoxGeometry(w * .7, 1.4, 3.2), this.concreteMat);
502:     dock.position.set(bx, .85, bz + d / 2 + 1.6); dock.castShadow = true; this.root.add(dock);
503:     // containers
504:     const colors = [0x8e3b32, 0x2e5f7a, 0x7c6a2e, 0x356b4a, 0x7a4a32];
505:     for (let i = 0; i < 4 + Math.floor(rng() * 5); i++) {
506:       const cw = 6, ch = 2.6, cd = 2.5;
507:       const cont = new THREE.Mesh(new THREE.BoxGeometry(cw, ch, cd), new THREE.MeshStandardMaterial({ color: pick(colors), roughness: .8, metalness: .3 }));
508:       cont.position.set(x - 24 + rng() * 48, .6 + (rng() > .8 ? ch : 0), z + 24 + rng() * 8);
509:       cont.rotation.y = rng() > .5 ? 0 : Math.PI / 2;
510:       cont.castShadow = true; this.root.add(cont);
511:     }
