516:     const w = 22 + rng() * 18, d = 24 + rng() * 16, h = 22 + rng() * 44;
517:     const bx = x + (rng() - .5) * 18, bz = z + (rng() - .5) * 10;
518:     this.addBuilding(bx, bz, w, d, h, 'midrise', Math.floor(rng() * 4));
519:     this.addRoofDetails(bx, bz, w, d, h + .2, rng, h > 50 ? 'tower' : 'normal');
520:     this.addBalconies(bx, bz, w, d, h, rng);
