523:   buildPark(block, rng) {
524:     const { x, z } = block;
525:     block.isPark = true;
526:     // path
527:     const pathMat = new THREE.MeshStandardMaterial({ color: 0x9a8f7a, roughness: 1 });
528:     const p1 = new THREE.Mesh(new THREE.PlaneGeometry(6, 68), pathMat);
529:     p1.rotation.x = -Math.PI / 2; p1.position.set(x, .17, z); this.root.add(p1);
530:     const p2 = new THREE.Mesh(new THREE.PlaneGeometry(68, 6), pathMat);
531:     p2.rotation.x = -Math.PI / 2; p2.position.set(x, .171, z); this.root.add(p2);
532:     // pond
533:     const pond = new THREE.Mesh(new THREE.CircleGeometry(11, 32), new THREE.MeshStandardMaterial({ color: 0x1b4d63, roughness: .15, metalness: .5, transparent: true, opacity: .9 }));
534:     pond.rotation.x = -Math.PI / 2; pond.position.set(x - 14, .18, z + 15); this.root.add(pond);
535:     const fountain = new THREE.Group(); fountain.position.set(x + 15, .2, z - 14);
