739:   signalState(node, axis, time) {
740:     if (!node.hasLights) return 'green';
741:     const t = (time + (node.i * 1.7 + node.j * 2.3)) % 26;
742:     if (axis === 'x') {
743:       if (t < 9) return 'green';
744:       if (t < 11) return 'yellow';
745:       if (t < 24) return 'red';
746:       return 'yellow';
747:     }
748:     if (t < 11) return 'red';
749:     if (t < 15) return 'green';
750:     if (t < 24) return 'red';
751:     if (t < 26) return 'green';
752:     return 'red';
753:   }
