852:   update(dt, elapsed, playerPos) {
853:     this.updateSignals(elapsed);
854:     if (this.water) {
855:       this.water.material.uniforms.time.value = elapsed;
856:     }
857:     for (const c of this.clouds) {
858:       c.position.x += c.userData.speed * dt;
859:       if (c.position.x > 900) c.position.x = -900;
860:       c.position.z += c.userData.speed * dt * .1;
861:       if (c.position.z > 700) c.position.z = -700;
862:     }
863:     if (this.lampGlow) this.lampGlow.rotation.y += 0;
864:     if (this.stars) this.stars.rotation.y = elapsed * .002;
865:     for (const a of this.animated) {
866:       if (a.type === 'beacon') a.mesh.material = this.warmMat;
867:     }
868:     if (this.monorail) this.monorail.update(dt, elapsed);
869:     if (this.rail) this.rail.update(dt, elapsed);
870:     if (this.highwayCars.length) {
871:       for (const c of this.highwayCars) {
872:         c.position.z += c.userData.speed * dt;
873:         if (c.position.z > 700) { c.position.z = -700; c.position.x = c.userData.lane; }
874:       }
875:     }
876:     this.updateFactorySmoke(dt, elapsed);
877:     this.updateFireflies(dt, elapsed);
878:   }
