895:   updateFireflies(dt, elapsed) {
896:     if (!this.fireflyPoints) return;
897:     this.fireflyPoints.material.opacity = (this.night > .5 ? .8 : 0) * (this.weather === 'clear' ? 1 : .15);
898:     this.fireflyPoints.position.y = .6 + Math.sin(elapsed * .8) * .1;
899:   }
