73:   addServiceLights() {
74:     const g = new THREE.Group();
75:     const redM = new THREE.MeshBasicMaterial({ color: 0xff2020, toneMapped: false });
76:     const blueM = new THREE.MeshBasicMaterial({ color: 0x2a5bff, toneMapped: false });
77:     const y = this.type === 'motorcycle' ? 1.2 : this.cfg.height + (this.type === 'bus' ? .1 : .02);
78:     const geo = new THREE.BoxGeometry(this.type === 'fire' ? 1.4 : .55, .16, .38);
79:     const r = new THREE.Mesh(geo, redM); r.position.set(-.3, y, this.type === 'sedan' ? 0 : 0);
80:     const b = new THREE.Mesh(geo, blueM); b.position.set(.3, y, 0);
