367:     ctx.save(); ctx.translate(px, py); ctx.rotate(-g.player.heading + Math.PI);
368:     ctx.fillStyle = '#5be0ff'; ctx.shadowColor = '#5be0ff'; ctx.shadowBlur = 16;
369:     ctx.beginPath(); ctx.moveTo(0, 14); ctx.lineTo(-9, -9); ctx.lineTo(0, -4); ctx.lineTo(9, -9); ctx.closePath(); ctx.fill();
370:     ctx.restore();
371:     this.el.mapPos.textContent = `${Math.round(g.player.pos.x)}, ${Math.round(g.player.pos.z)} · ${g.city.districtAt(g.player.pos.x, g.player.pos.z)}`;
