607: function loopPoints(progress, perimeter, R) {
608:   const seg = perimeter / 4;
609:   let p = progress % perimeter;
610:   if (p < seg) return { x: -R + p, z: -R, angle: 0 };
611:   p -= seg;
612:   if (p < seg) return { x: R, z: -R + p, angle: Math.PI / 2 };
613:   p -= seg;
614:   if (p < seg) return { x: R - p, z: R, angle: Math.PI };
615:   p -= seg;
616:   return { x: -R, z: R - p, angle: -Math.PI / 2 };
617: }
