const THEMES = {
  apartment: { name: 'The Hale Apartments', wall: 0x6e6257, floor: 0x5d4c3c, accent: 0x8b6b4d, light: 0xffd7a8 },
  shop: { name: 'Corner Market', wall: 0x6c7a70, floor: 0x8a8d88, accent: 0x3f7a5a, light: 0xf2f4e8 },
